"""Local, source-preserving library. SQLite is the authority; the old site is separate."""
from __future__ import annotations

import csv
import hashlib
import json
import math
import re
import sqlite3
import unicodedata
import urllib.request
from datetime import date, datetime, timezone
from pathlib import Path
from uuid import uuid4

ROOT = Path(__file__).resolve().parents[1]
DEFAULT_DB = ROOT / 'data/library/library.sqlite3'
CATEGORIES = ('tv','movie','ova','ona','anime_other','manga','novel','book','game','music','live_action','other')
TOPICS = ('unclassified','work','life','channel','general')
RECORDING_KINDS = ('talk','tea','op_ed','screening','other')


def dumps(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True)


def now():
    return datetime.now(timezone.utc).isoformat()


def connect(path=DEFAULT_DB):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    db = sqlite3.connect(path, timeout=30)
    db.row_factory = sqlite3.Row
    db.execute('PRAGMA foreign_keys=ON')
    db.execute('PRAGMA busy_timeout=30000')
    return db


def initialize(db):
    schema=(ROOT / 'database/schema.sql').read_text(encoding='utf-8')
    old_columns={r['name'] for r in db.execute('PRAGMA table_info(aliases)')}
    if old_columns and 'target_kind' not in old_columns:
        path=Path(db.execute('PRAGMA database_list').fetchone()['file'])
        backup_dir=path.parent/'backups';backup_dir.mkdir(exist_ok=True)
        backup=sqlite3.connect(backup_dir/('before-schema-v2-'+datetime.now().strftime('%Y%m%d-%H%M%S-%f')+'.sqlite3'))
        db.backup(backup);backup.close()
    db.executescript(schema)
    if old_columns and 'target_kind' not in old_columns:
        with db:
            definition='CREATE TABLE aliases_v2 ('+schema.split('CREATE TABLE IF NOT EXISTS aliases (',1)[1].split(');',1)[0]+')'
            db.execute(definition)
            fields=','.join(old_columns)
            db.execute(f'INSERT INTO aliases_v2 ({fields}) SELECT {fields} FROM aliases')
            db.execute('DROP TABLE aliases')
            db.execute('ALTER TABLE aliases_v2 RENAME TO aliases')
        db.executescript(schema)  # Restore indexes removed with the old table.
    db.execute("INSERT OR REPLACE INTO meta VALUES ('schema_version','2')")
    db.execute("INSERT OR IGNORE INTO meta VALUES ('library_id',?)",(uuid4().hex,))
    db.commit()


def rows(db, sql, args=()):
    return [dict(r) for r in db.execute(sql, args)]


def insert(db, table, value):
    cols = list(value)
    db.execute(f'INSERT OR IGNORE INTO {table} ({",".join(cols)}) VALUES ({",".join("?" for _ in cols)})', list(value.values()))


def norm(text):
    return ''.join(c for c in unicodedata.normalize('NFKC', text).casefold()
                   if unicodedata.category(c)[0] not in ('P','S','Z','C'))


def stable(*parts):
    return hashlib.sha256(dumps(parts).encode('utf-8')).hexdigest()[:24]


def quarter(value):
    try:
        d = date.fromisoformat(value)
        return f'{d.year:04d}-{((d.month-1)//3)*3+1:02d}'
    except (ValueError, TypeError):
        return None


def work_category(meta):
    t, p = meta.get('type',0), meta.get('platform','')
    if t == 2:
        return {'TV':'tv','剧场版':'movie','OVA':'ova','WEB':'ona'}.get(p, 'anime_other')
    if t == 1:
        return 'novel' if '小说' in p else 'manga' if '漫画' in p else 'book'
    return {3:'music',4:'game',6:'live_action'}.get(t,'other')


def add_alias(db, term, work_id, kind, status, evidence, scope='', series_id=None):
    if not term or not norm(term):
        return
    target_kind='series' if series_id else 'work'
    work_id=None if series_id else work_id
    aid = 'alias:' + stable(norm(term), series_id or work_id, scope)
    insert(db,'aliases',dict(id=aid,term=term.strip(),normalized=norm(term),work_id=work_id,
                           series_id=series_id,target_kind=target_kind,kind=kind,status=status,scope=scope,evidence=dumps(evidence)))
    # An edited alias keeps its stable ID, even when its normalized term changes.
    row=db.execute('SELECT id FROM aliases WHERE normalized=? AND work_id IS ? AND series_id IS ? AND scope=?',
                      (norm(term),work_id,series_id,scope)).fetchone()
    return row[0] if row else None


def add_bangumi_work(db, meta, source='Bangumi', csv_name=None, csv_quarter=None):
    sid = int(meta['id'])
    wid = f'bgm:{sid}'
    cat = work_category(meta)
    cq = (csv_quarter[:4]+'-'+csv_quarter[4:]) if csv_quarter and csv_quarter!='999999' else None
    q = (cq or quarter(meta.get('date'))) if cat=='tv' else None
    insert(db,'works',dict(id=wid,bangumi_id=sid,name=csv_name or meta.get('name_cn') or meta.get('name') or f'作品 {sid}',
        original_name=meta.get('name') or '',type=meta.get('type',0),category=cat,platform=meta.get('platform') or '',
        air_date=meta.get('date'),quarter=q,csv_quarter=csv_quarter,
        quarter_basis='non-tv' if cat!='tv' else 'CSV' if cq else 'Bangumi date' if q else 'unknown',
        cover_url=((meta.get('images') or {}).get('large') or (meta.get('images') or {}).get('common') or '').replace('http://','https://'),
        summary=meta.get('summary') or '',metadata_source=source))
    names = [(meta.get('name'),'original_name'),(meta.get('name_cn'),'name_cn'),(csv_name,'csv_name')]
    for field in meta.get('infobox',[]):
        if field.get('key') in ('别名','别称'):
            value = field.get('value')
            values = [x.get('v') for x in value if isinstance(x,dict)] if isinstance(value,list) else [value]
            names.extend((v,'bangumi_alias') for v in values if isinstance(v,str))
    for term, kind in names:
        add_alias(db,term,wid,kind,'reference',{'source':source,'bangumi_id':sid})
    return wid


def bangumi_request(path, payload=None):
    request = urllib.request.Request('https://api.bgm.tv'+path,
        data=dumps(payload).encode('utf-8') if payload is not None else None,
        headers={'User-Agent':'FunshikiLibrary/1.0 (https://github.com/Juvenile-A3/funshiki-anime-index)',
                 'Content-Type':'application/json','Accept':'application/json'})
    with urllib.request.urlopen(request,timeout=20) as response:
        return json.load(response)


def bangumi_search(query, subject_type=None, offset=0):
    payload = {'keyword':query,'sort':'match'}
    if subject_type:
        payload['filter']={'type':[int(subject_type)]}
    return bangumi_request(f'/v0/search/subjects?limit=20&offset={max(0,int(offset))}',payload)


def entity(db, table, eid):
    if table not in ('entries','recordings','works','aliases','series','alias_exclusions'):
        raise ValueError('无效记录类型')
    result = db.execute(f'SELECT * FROM {table} WHERE id=?',(eid,)).fetchone()
    if not result:
        raise ValueError('记录不存在')
    result = dict(result)
    if table == 'entries':
        result['links'] = rows(db,'SELECT * FROM entry_works WHERE entry_id=? ORDER BY work_id',(eid,))
    if table == 'series':
        result['members'] = rows(db,'SELECT * FROM series_works WHERE series_id=? ORDER BY work_id',(eid,))
    return result


def log_change(db, table, eid, before, after, reason):
    db.execute('INSERT INTO audit_log (at,entity,entity_id,reason,before_json,after_json) VALUES (?,?,?,?,?,?)',
               (now(),table,eid,reason,dumps(before) if before is not None else None,dumps(after)))
    from library_workflow import audit_context
    actor,origin,package_id=audit_context.get()
    db.execute('INSERT INTO audit_details VALUES(last_insert_rowid(),?,?,?)',(actor,origin,package_id))


def validate_date(value):
    if value is not None:
        date.fromisoformat(value)


def validate_quarter(value):
    if value is not None and not re.fullmatch(r'\d{4}-(01|04|07|10)',value):
        raise ValueError('季度请使用 YYYY-01/04/07/10；未知留空')


def update_entity(db, table, eid, patch, revision, reason=''):
    if reason is None: reason=''
    if not isinstance(reason,str): raise ValueError('修改依据应为文字，可留空')
    reason=reason.strip()
    allowed = {
        'recordings':{'title','kind','live_date','published_date','program_quarter','danmaku','description'},
        'works':{'name','original_name','category','platform','air_date','quarter','cover_url','summary'},
        'entries':{'description','p','start','end','category','work_ids'},
        'aliases':{'term','work_id','series_id','target_kind','scope','status'},
        'series':{'name','work_ids'},
        'alias_exclusions':{'excluded'},
    }
    if table not in allowed or set(patch)-allowed[table]:
        raise ValueError('包含不允许修改的字段')
    before = entity(db,table,eid)
    if type(revision)!=int or revision != before['revision']:
        raise ValueError('记录已被修改，请刷新后再保存')
    value = {**before,**patch}
    if table=='alias_exclusions' and (type(value['excluded']) not in (int,bool) or value['excluded'] not in (0,1)):
        raise ValueError('原文关联状态无效')
    if table in ('works','recordings'):
        if not value.get('name' if table=='works' else 'title','').strip():
            raise ValueError('名称不能为空')
    if table=='recordings':
        if value['kind'] not in RECORDING_KINDS or value['danmaku'] not in ('yes','no','unknown'):
            raise ValueError('录播分类或弹幕状态无效')
        validate_date(value['live_date']); validate_date(value['published_date']); validate_quarter(value['program_quarter'])
        patch['recording_quarter']=quarter(value['live_date'] or value['published_date'])
        patch['date_basis']='user live_date' if value['live_date'] else 'published fallback'
    if table=='works':
        if value['category'] not in CATEGORIES:
            raise ValueError('作品分类无效')
        validate_date(value['air_date']); validate_quarter(value['quarter'])
        patch['quarter']=value['quarter'] if value['category']=='tv' else None
        patch['quarter_basis']='user' if value['category']=='tv' else 'non-tv'
        if value['cover_url'] and not value['cover_url'].startswith('https://'):
            raise ValueError('封面链接须为 HTTPS')
    if table=='entries':
        ids = patch.pop('work_ids',[x['work_id'] for x in before['links'] if x['status']!='candidate'])
        if not isinstance(ids,list) or any(not isinstance(w,str) for w in ids) or len(ids)!=len(set(ids)):
            raise ValueError('作品关联无效或重复')
        if value['category'] not in TOPICS or (value['category'] in ('life','channel','general') and ids):
            raise ValueError('非作品话题不能关联作品')
        if value['category']=='work' and not ids:
            raise ValueError('作品话题请关联至少一部作品')
        if ids and value['category']!='work':
            raise ValueError('有关联作品时请选择作品话题')
        timing_changed=any(k in patch and patch[k]!=before[k] for k in ('p','start','end'))
        if timing_changed and (type(value['p'])!=int or value['p']<1):
            raise ValueError('分 P 必须是正整数')
        pg = db.execute('SELECT * FROM pages WHERE recording_id=? AND p=?',(value['recording_id'],value['p'])).fetchone()
        if timing_changed and not pg:
            raise ValueError('该分 P 尚无来源元数据，请先核对录播分 P')
        for field in ('start','end'):
            num=value[field]
            if num is None and field=='end': continue
            if type(num) not in (int,float) or not math.isfinite(num) or num<0:
                raise ValueError('时轴须为有限的非负秒数')
            if timing_changed and pg['duration'] is not None and num>pg['duration']:
                raise ValueError('时轴超过该分 P 的时长')
        if value['end'] is not None and value['end']<=value['start']:
            raise ValueError('结束时间必须晚于开始时间')
        for wid in ids:
            entity(db,'works',wid)
        patch.update(cid=pg['cid'] if pg else before['cid'],status='pending' if value['category']=='unclassified' else 'confirmed')
        # Original warnings stay available even after a human corrects a timestamp.
        db.execute('DELETE FROM entry_works WHERE entry_id=?',(eid,))
        for wid in ids:
            insert(db,'entry_works',dict(entry_id=eid,work_id=wid,status='confirmed',method='user',evidence=dumps({'reason':reason})))
    if table=='aliases':
        if value['status'] not in ('pending','confirmed','rejected','reference') or not norm(value['term']):
            raise ValueError('黑话文本或状态无效')
        if value['scope'] and not db.execute('SELECT 1 FROM recordings WHERE id=?',(value['scope'],)).fetchone():
            raise ValueError('范围只能留空（全局）或填写库内 BV 号')
        if value['target_kind']=='series':
            entity(db,'series',value['series_id']);patch['work_id']=None
        elif value['target_kind']=='work':
            entity(db,'works',value['work_id']);patch['series_id']=None
        else: raise ValueError('黑话只能指向具体作品或系列')
        patch['normalized']=norm(value['term'])
    if table=='series':
        if not value['name'].strip(): raise ValueError('系列名称不能为空')
        patch['normalized']=norm(value['name'])
        members=patch.pop('work_ids',None)
        if members is not None:
            if not isinstance(members,list) or not members or len(set(members))!=len(members): raise ValueError('请选择不重复的系列作品')
            for wid in members: entity(db,'works',wid)
            db.execute('DELETE FROM series_works WHERE series_id=?',(eid,))
            for wid in members: insert(db,'series_works',dict(series_id=eid,work_id=wid,evidence=dumps({'method':'user','reason':reason})))
    patch['revision']=revision+1
    db.execute(f'UPDATE {table} SET '+','.join(f'{k}=?' for k in patch)+' WHERE id=?',(*patch.values(),eid))
    after=entity(db,table,eid)
    log_change(db,table,eid,before,after,reason)
    return after


def create_manual_work(db, name, category='other'):
    if not isinstance(name,str) or not name.strip() or category not in CATEGORIES:
        raise ValueError('请填写作品名称并选择分类')
    wid='local:'+uuid4().hex
    insert(db,'works',dict(id=wid,name=name.strip(),category=category,quarter_basis='unknown',metadata_source='user'))
    log_change(db,'works',wid,None,entity(db,'works',wid),'手工添加未关联 Bangumi 的作品')
    return wid


def create_series(db,name,work_ids,reason=''):
    if not isinstance(name,str) or not name.strip() or not isinstance(work_ids,list) or not work_ids or len(set(work_ids))!=len(work_ids):
        raise ValueError('请填写系列名称并选择不重复的作品')
    for wid in work_ids:entity(db,'works',wid)
    sid='series:'+stable(norm(name))
    if db.execute('SELECT 1 FROM series WHERE normalized=?',(norm(name),)).fetchone():raise ValueError('系列已存在，请打开该系列修改成员')
    insert(db,'series',dict(id=sid,name=name.strip(),normalized=norm(name),evidence=dumps({'method':'user'}),revision=1))
    for wid in work_ids:insert(db,'series_works',dict(series_id=sid,work_id=wid,evidence=dumps({'method':'user'})))
    log_change(db,'series',sid,None,entity(db,'series',sid),reason or '')
    return sid


def undo(db, audit_id):
    audit=db.execute('SELECT * FROM audit_log WHERE id=?',(audit_id,)).fetchone()
    if not audit or not audit['before_json']:
        raise ValueError('只能撤销对已有记录的修改')
    current=entity(db,audit['entity'],audit['entity_id'])
    expected=json.loads(audit['after_json'])
    if audit['entity']=='aliases':
        expected.setdefault('target_kind','work');expected.setdefault('series_id',None)
    if dumps(current)!=dumps(expected):
        raise ValueError('此后记录已变化，请先撤销较新的修改')
    old=json.loads(audit['before_json']); links=old.pop('links',None);members=old.pop('members',None)
    if audit['entity']=='aliases':
        old.setdefault('target_kind','work');old.setdefault('series_id',None)
    old['revision']=current['revision']+1
    db.execute(f'UPDATE {audit["entity"]} SET '+','.join(f'{k}=?' for k in old)+' WHERE id=?',(*old.values(),audit['entity_id']))
    if links is not None:
        db.execute('DELETE FROM entry_works WHERE entry_id=?',(audit['entity_id'],))
        for link in links: insert(db,'entry_works',link)
    if members is not None:
        db.execute('DELETE FROM series_works WHERE series_id=?',(audit['entity_id'],))
        for member in members: insert(db,'series_works',member)
    after=entity(db,audit['entity'],audit['entity_id'])
    log_change(db,audit['entity'],audit['entity_id'],current,after,f'撤销修改 #{audit_id}')
    return after


def clean_term(text):
    text=re.sub(r'^\s*(?:时光机之|简评|聊聊|聊|《|「|【)','',text,flags=re.I)
    text=re.sub(r'(?:切片|杂谈|简评|pv|预告片|op|ed|鉴赏)(?:\s*\+.*)?$','',text,flags=re.I)
    return text.strip(' 《》「」【】+：:，,。 .')


def contains_term(text, term):
    if len(term)<2: return False
    if re.fullmatch(r'[a-z0-9]+',term):
        return bool(re.search(r'(?<![a-z0-9])'+re.escape(term)+r'(?![a-z0-9])',text))
    return term in text


def recognize(db):
    from library_recognition import recognize_library
    count=recognize_library(db)
    from library_workflow import refresh_confidence
    refresh_confidence(db)
    return count


def statistics(db):
    result={t:db.execute(f'SELECT COUNT(*) FROM {t}').fetchone()[0]
            for t in ('recordings','pages','notes','entries','works','series','aliases','audit_log')}
    result['timeline_notes']=db.execute('SELECT COUNT(*) FROM notes WHERE has_timeline=1').fetchone()[0]
    result['pending_entries']=db.execute("SELECT COUNT(*) FROM entries WHERE status='pending'").fetchone()[0]
    result['entries_with_candidates']=db.execute("SELECT COUNT(DISTINCT entry_id) FROM entry_works WHERE status='candidate'").fetchone()[0]
    result['linked_entries']=db.execute("SELECT COUNT(DISTINCT entry_id) FROM entry_works WHERE status!='candidate'").fetchone()[0]
    result['warning_entries']=db.execute("SELECT COUNT(*) FROM entries WHERE warnings!='[]'").fetchone()[0]
    result['high_confidence_entries']=db.execute("SELECT COUNT(*) FROM entry_confidence c JOIN entries e ON e.id=c.entry_id WHERE e.status='pending'").fetchone()[0]
    result['missing_pages']=db.execute("SELECT COUNT(*) FROM recordings WHERE danmaku='unknown'").fetchone()[0]
    result['without_timeline']=db.execute('SELECT COUNT(*) FROM recording_overview WHERE entry_count=0').fetchone()[0]
    result['alias_status']=rows(db,'SELECT status,COUNT(*) count FROM aliases GROUP BY status')
    result['work_categories']=rows(db,'SELECT category,COUNT(*) count FROM works GROUP BY category')
    result['integrity']=db.execute('PRAGMA integrity_check').fetchone()[0]
    result['foreign_key_errors']=rows(db,'PRAGMA foreign_key_check')
    return result


def export_library(db, destination):
    destination=Path(destination); destination.mkdir(parents=True,exist_ok=True)
    tables=('recordings','pages','recording_checks','notes','note_reviews','entries','entry_reviews','entry_confidence','works','entry_works','series','series_works','aliases','alias_exclusions','retired_aliases','sources','observations','audit_log','audit_details')
    snapshot={'schema_version':2,'exported_at':now(),**{t:rows(db,f'SELECT * FROM {t}') for t in tables}}
    (destination/'library.json').write_text(json.dumps(snapshot,ensure_ascii=False,indent=2),encoding='utf-8')
    exports={
        '录播列表':'SELECT * FROM recording_overview',
        '时轴与作品':'SELECT * FROM timeline_overview',
        '作品':'SELECT * FROM works',
        '黑话与别名':'SELECT a.*,w.name work_name,w.bangumi_id,s.name series_name FROM aliases a LEFT JOIN works w ON a.work_id=w.id LEFT JOIN series s ON s.id=a.series_id',
        '系列作品':'SELECT s.name series_name,sw.*,w.name work_name,w.bangumi_id,w.air_date,w.quarter,w.category FROM series_works sw JOIN series s ON s.id=sw.series_id JOIN works w ON w.id=sw.work_id',
        '笔记复核':'SELECT e.recording_id,e.note_id,e.p,e.start,e.description,r.* FROM entry_reviews r JOIN entries e ON e.id=r.entry_id ORDER BY e.recording_id,e.p,e.start',
        '弹幕版核查':'SELECT r.title,c.* FROM recording_checks c JOIN recordings r ON r.id=c.recording_id',
        '时轴作品关联':'''SELECT e.id entry_id,e.recording_id,e.source_locator,e.p,e.start,e.end,e.description,
                         ew.status,ew.method,ew.evidence,w.id work_id,w.name work_name,w.bangumi_id,
                         w.category,w.quarter,w.cover_url FROM entry_works ew JOIN entries e ON ew.entry_id=e.id
                         JOIN works w ON ew.work_id=w.id ORDER BY e.recording_id,e.p,e.start,w.id''',
    }
    labels={'id':'记录ID','title':'名称','kind':'类型','live_date':'录播日期','published_date':'投稿日期',
        'recording_quarter':'录播季度','program_quarter':'节目讨论季度','date_basis':'日期依据','danmaku':'弹幕版状态',
        'description':'描述','revision':'修改版本','timeline_notes':'有时轴笔记数','entry_count':'时轴数','pending_count':'待核对数',
        'recording_id':'录播BV号','note_id':'笔记ID','source_kind':'来源类型','source_locator':'来源位置','p':'分P',
        'cid':'当前CID','source_cid':'原始CID','start':'开始秒数','end':'结束秒数','original_description':'原始描述',
        'category':'分类','status':'状态','warnings':'来源警告','recording_title':'录播名称','author':'笔记作者',
        'note_url':'原笔记链接','variant':'版本','duration':'分P时长','work_names':'已关联作品','bangumi_ids':'已关联BangumiID',
        'candidates':'候选作品','bangumi_id':'BangumiID','name':'作品名称','original_name':'作品原名','type':'Bangumi类型',
        'platform':'作品形式','air_date':'播出发售日期','quarter':'TV作品季度','csv_quarter':'CSV原始季度',
        'quarter_basis':'作品季度依据','cover_url':'Bangumi封面','summary':'作品简介','metadata_source':'元数据来源',
        'term':'黑话别名','normalized':'规范化检索词','work_id':'作品内部ID','scope':'适用范围BV号或空白全局',
        'evidence':'对应依据','work_name':'对应作品名称','entry_id':'时轴ID','method':'识别方法',
        'series_id':'系列ID','series_name':'系列名称','target_kind':'指代类型','reviewed_at':'复核时间',
        'checked_at':'核查时间','page_count':'完整分P数量','context_kind':'讨论背景','context_quarter':'参考季度'}
    for name,sql in exports.items():
        cursor=db.execute(sql); columns=[d[0] for d in cursor.description]
        with (destination/f'{name}.csv').open('w',encoding='utf-8-sig',newline='') as handle:
            writer=csv.writer(handle); writer.writerow([labels.get(col,col) for col in columns])
            for row in cursor:
                # Avoid spreadsheet formula execution when opening third-party note text.
                writer.writerow(["'"+v if isinstance(v,str) and v.startswith(('=','+','-','@','\t','\r')) else v for v in row])
    (destination/'检查报告.json').write_text(json.dumps(statistics(db),ensure_ascii=False,indent=2),encoding='utf-8')
    return str(destination)

