"""Grouped nickname decisions and durable, per-timeline occurrence exclusions."""
import hashlib,json
from collections import defaultdict
from library import rows,entity,norm,stable,dumps,update_entity,log_change,insert,add_alias
from library_workflow import term_present


def exclusion_id(entry_id,term):return 'exclusion:'+stable(entry_id,norm(term))


def excluded_terms(db):
    result=defaultdict(set)
    if not db.execute("SELECT 1 FROM sqlite_master WHERE name='alias_exclusions'").fetchone():return result
    for e in rows(db,'SELECT entry_id,normalized FROM alias_exclusions WHERE excluded=1'):result[e['entry_id']].add(e['normalized'])
    return result


def prune_excluded_evidence(db):
    """Remove the excluded keyword's derived evidence, retaining independent links."""
    exclusions=excluded_terms(db)
    def terms(value):
        found=set()
        if isinstance(value,dict):
            if isinstance(value.get('term'),str):found.add(norm(value['term']))
            for x in value.values():found.update(terms(x))
        elif isinstance(value,list):
            for x in value:found.update(terms(x))
        return found
    for eid,blocked in exclusions.items():
        for link in rows(db,"SELECT * FROM entry_works WHERE entry_id=? AND status='candidate'",(eid,)):
            data=json.loads(link['evidence']);evs=data if isinstance(data,list) else [data]
            remaining=[e for e in evs if not terms(e).intersection(blocked)]
            if len(remaining)==len(evs):continue
            if remaining:db.execute('UPDATE entry_works SET evidence=? WHERE entry_id=? AND work_id=?',(dumps(remaining),eid,link['work_id']))
            else:db.execute('DELETE FROM entry_works WHERE entry_id=? AND work_id=?',(eid,link['work_id']))


def refresh_group_candidates(db,tokens,only_entry=None):
    """Re-evaluate the chosen keywords without disturbing other work evidence."""
    from library_review import Catalog,infer_context
    tokens={norm(t) for t in tokens};catalog=Catalog(db,metadata={});exclusions=excluded_terms(db)
    recordings={r['id']:r for r in rows(db,'SELECT * FROM recordings')}
    contexts={r['entry_id']:r for r in rows(db,'SELECT entry_id,context_kind,context_quarter FROM entry_reviews')}
    for e in rows(db,"SELECT * FROM entries WHERE status='pending' AND category NOT IN ('life','channel','general')"+(' AND id=?' if only_entry else ''),(only_entry,) if only_entry else ()):
        matched={t for t in tokens if term_present(e['description'],t)}
        if not matched:continue
        for link in rows(db,"SELECT * FROM entry_works WHERE entry_id=? AND status='candidate'",(e['id'],)):
            data=json.loads(link['evidence']);evs=data if isinstance(data,list) else [data]
            keep=[ev for ev in evs if not (isinstance(ev,dict) and (norm(ev.get('term','')) in matched or any(norm(x.get('term','')) in matched for x in ev.get('matches',[]) if isinstance(x,dict))))]
            if len(keep)==len(evs):continue
            if keep:db.execute('UPDATE entry_works SET evidence=? WHERE entry_id=? AND work_id=?',(dumps(keep),e['id'],link['work_id']))
            else:db.execute('DELETE FROM entry_works WHERE entry_id=? AND work_id=?',(e['id'],link['work_id']))
        ctx=contexts.get(e['id']);context={'kind':ctx['context_kind'],'quarter':ctx['context_quarter']} if ctx else infer_context(recordings[e['recording_id']],e['description'])
        active=catalog.terms(e['description'],e['recording_id'])
        for token in (matched & active)-exclusions[e['id']]:
            selected,_=catalog.choose(token,recordings[e['recording_id']],e['description'],context)
            for wid,ev in selected.items():
                existing=db.execute('SELECT * FROM entry_works WHERE entry_id=? AND work_id=?',(e['id'],wid)).fetchone()
                if existing:
                    old=json.loads(existing['evidence']);old=old if isinstance(old,list) else [old]
                    if ev not in old:db.execute('UPDATE entry_works SET evidence=? WHERE entry_id=? AND work_id=?',(dumps(old+[ev]),e['id'],wid))
                else:insert(db,'entry_works',{'entry_id':e['id'],'work_id':wid,'status':'candidate','method':'auto:keyword_review','evidence':dumps([ev])})


def set_occurrence(db,entry_id,term,excluded,revision):
    if type(excluded) is not bool or not norm(term):raise ValueError('无效的原文解绑操作')
    entry=entity(db,'entries',entry_id);eid=exclusion_id(entry_id,term)
    existing=db.execute('SELECT * FROM alias_exclusions WHERE id=?',(eid,)).fetchone()
    if existing:return update_entity(db,'alias_exclusions',eid,{'excluded':int(excluded)},revision)
    if revision!=0:raise ValueError('原文关联已变化，请重新展开')
    if not db.execute('SELECT 1 FROM aliases WHERE normalized=?',(norm(term),)).fetchone():raise ValueError('黑话不存在')
    value={'id':eid,'entry_id':entry_id,'term':term,'normalized':norm(term),'excluded':int(excluded),'revision':1}
    insert(db,'alias_exclusions',value);log_change(db,'alias_exclusions',eid,None,value,'')
    return value


def fingerprint(aliases):return hashlib.sha256(dumps(sorted((a['id'],a['revision']) for a in aliases)).encode()).hexdigest()


def candidates(db,token):
    return rows(db,'''SELECT a.*,w.name work_name,w.bangumi_id,w.category work_category,w.cover_url,w.air_date,w.quarter,s.name series_name
        FROM aliases a LEFT JOIN works w ON w.id=a.work_id LEFT JOIN series s ON s.id=a.series_id
        WHERE a.normalized=? ORDER BY CASE a.status WHEN 'confirmed' THEN 0 WHEN 'pending' THEN 1 WHEN 'reference' THEN 2 ELSE 3 END,a.id''',(token,))


def group_list(db,query):
    q=query.get('q','').strip();page=max(1,int(query.get('page',1)));conditions=[];args=[]
    if q:
        conditions.append('(a.term LIKE ? OR w.name LIKE ? OR s.name LIKE ?)');args.extend(['%'+q+'%']*3)
    for key,column in [('status','a.status'),('target_kind','a.target_kind'),('work','a.work_id'),('kind','a.kind')]:
        if query.get(key):conditions.append(column+'=?');args.append(query[key])
    source=' FROM aliases a LEFT JOIN works w ON w.id=a.work_id LEFT JOIN series s ON s.id=a.series_id'
    where=' WHERE '+' AND '.join(conditions) if conditions else ''
    total=db.execute('SELECT COUNT(DISTINCT a.normalized)'+source+where,args).fetchone()[0]
    tokens=rows(db,'SELECT DISTINCT a.normalized'+source+where+' ORDER BY a.normalized LIMIT 50 OFFSET ?',(*args,(page-1)*50))
    items=[]
    for row in tokens:
        aliases=candidates(db,row['normalized']);first=aliases[0]
        items.append({'id':'alias-group:'+stable(row['normalized']),'normalized':row['normalized'],'term':first['term'],
            'status':'pending' if any(a['status']=='pending' for a in aliases) else first['status'],
            'fingerprint':fingerprint(aliases),'revision':fingerprint(aliases),'candidates':aliases})
    return {'items':items,'total':total,'page':page,'limit':50,'unit':'组黑话'}


def occurrences(db,token):
    token=norm(token);aliases=candidates(db,token)
    if not aliases:raise ValueError('黑话不存在')
    scopes={a['scope'] for a in aliases};evidence_ids=set()
    def walk(value):
        if isinstance(value,dict):
            if isinstance(value.get('entry_id'),str):evidence_ids.add(value['entry_id'])
            for x in value.values():walk(x)
        elif isinstance(value,list):
            for x in value:walk(x)
    for a in aliases:
        try:walk(json.loads(a['evidence']))
        except (TypeError,ValueError):pass
    overrides={e['entry_id']:e for e in rows(db,'SELECT * FROM alias_exclusions WHERE normalized=?',(token,))}
    result=[]
    for e in rows(db,'''SELECT e.id,e.recording_id,e.note_id,e.p,e.start,e.end,e.description,e.original_description,e.source_locator,
        r.title recording_title,n.author,n.url note_url FROM entries e JOIN recordings r ON r.id=e.recording_id
        LEFT JOIN notes n ON n.id=e.note_id ORDER BY COALESCE(r.live_date,r.published_date) DESC,e.recording_id,e.p,e.start,e.id'''):
        if '' not in scopes and e['recording_id'] not in scopes:continue
        matched=term_present(e['description'],token)
        if not matched and e['id'] not in evidence_ids and not term_present(e['original_description'],token) and e['id'] not in overrides:continue
        override=overrides.get(e['id'],{});e.update(excluded=bool(override.get('excluded')),exclusion_revision=override.get('revision',0),current_match=matched)
        result.append(e)
    return {'term':aliases[0]['term'],'normalized':token,'items':result,'total':len(result),'excluded':sum(e['excluded'] for e in result)}


def confirm_groups(db,groups):
    if not isinstance(groups,list) or not 1<=len(groups)<=50:raise ValueError('每次核对 1 至 50 组黑话')
    if len({norm(g['normalized']) for g in groups})!=len(groups):raise ValueError('黑话组重复')
    count=0
    for group in groups:
        aliases=candidates(db,norm(group['normalized']))
        if not aliases or fingerprint(aliases)!=group.get('fingerprint'):raise ValueError('黑话候选已变化，请重新读取本页')
        selected=group.get('selected_ids',[])
        if not isinstance(selected,list) or set(selected)-{a['id'] for a in aliases}:raise ValueError('选择了不属于这组黑话的候选')
        if not selected and not group.get('reject_all'):raise ValueError('请先选择这组黑话的指代对象，或使用“全部不对”')
        for a in aliases:
            desired='confirmed' if a['id'] in selected else 'rejected'
            # Source-provided names are retained unless explicitly chosen; pending
            # and previously reviewed candidates are considered together.
            if a['status']=='reference' and a['id'] not in selected:continue
            if a['status']!=desired:update_entity(db,'aliases',a['id'],{'status':desired},a['revision']);count+=1
    return {'confirmed':len(groups),'updated_candidates':count}

