FIELDS={'recordings':('title','kind','live_date','published_date','program_quarter','danmaku','description'),
        'works':('name','original_name','category','platform','air_date','quarter','cover_url','summary'),
        'aliases':('term','target','scope','status'), 'series':('name',),
        'alias_exclusions':('entry_id','term','normalized','excluded')}
TABLES=('works','series','recordings','entries','aliases','alias_exclusions')

def library_id(db):
    row=db.execute("SELECT value FROM meta WHERE key='library_id'").fetchone()
    if not row:
        value=uuid4().hex;db.execute("INSERT INTO meta VALUES('library_id',?)",(value,));return value
    return row[0]

def canonical(table,value):
    if value is None:return None
    if table=='entries':
        return {**{k:value[k] for k in ('description','p','start','end')},'assignment':{'category':value['category'],'status':value['status'],
            'work_ids':sorted(x['work_id'] for x in value.get('links',[]) if x['status']!='candidate')}}
    result={k:value.get(k) for k in FIELDS[table]}
    if table=='aliases':result['target']={k:value[k] for k in ('target_kind','work_id','series_id')}
    if table=='series':result['work_ids']=sorted(x['work_id'] for x in value.get('members',[]))
    return result

def snapshot(db):
    return {t:{r['id']:canonical(t,entity(db,t,r['id'])) for r in rows(db,'SELECT id FROM '+t)} for t in TABLES}

def create_bundle(db,destination):
    destination=Path(destination);destination.mkdir(exist_ok=True,parents=True)
    uid=uuid4().hex;folder=destination/('bundle-'+uid);folder.mkdir()
    copy_path=folder/'library.sqlite3';clone=connect(copy_path);db.backup(clone)
    base={'snapshot':snapshot(clone),'audit_id':clone.execute('SELECT COALESCE(MAX(id),0) FROM audit_log').fetchone()[0],
          'at':now(),'package_id':uid}
