'''
    cmd='@echo off\r\ncd /d "%~dp0"\r\nwhere py >nul 2>nul\r\nif errorlevel 1 (python start.py) else (py -3 start.py)\r\npause\r\n'
    with zipfile.ZipFile(target,'w',zipfile.ZIP_DEFLATED) as z:
