def export_changes(db,author='协作者'):
    stored=db.execute("SELECT value FROM meta WHERE key='collaboration_base'").fetchone()
    base=json.loads(stored[0]) if stored else {'snapshot':{},'audit_id':0}
    events=rows(db,'SELECT * FROM audit_log WHERE id>? ORDER BY id',(base['audit_id'],));first={}
    for e in events:first.setdefault((e['entity'],e['entity_id']),e)
    changes=[];dependencies={'works':{},'series':{}}
    def dependency(table,eid):
        if not eid or eid in dependencies[table]:return
        value=entity(db,table,eid);dependencies[table][eid]=value
        if table=='series':
            for m in value['members']:dependency('works',m['work_id'])
    for (table,eid),event in first.items():
        if table not in TABLES:continue
        value=entity(db,table,eid);after=canonical(table,value)
        before=base['snapshot'].get(table,{}).get(eid) if stored else canonical(table,json.loads(event['before_json']) if event['before_json'] else None)
        if before==after:continue
        changes.append({'table':table,'id':eid,'before':before,'after':after,'record':value if before is None else None})
        if table=='entries':
            for wid in after['assignment']['work_ids']:dependency('works',wid)
        if table=='aliases':
            if value['work_id']:dependency('works',value['work_id'])
            else:dependency('series',value['series_id'])
        if table=='series':
            for wid in after['work_ids']:dependency('works',wid)
    return {'format':'funshiki-changes-v1','library_id':library_id(db),'package_id':uuid4().hex,'author':str(author).strip()[:80] or '协作者',
            'created_at':now(),'changes':changes,'dependencies':dependencies}

def validate_package(db,package):
    if not isinstance(package,dict) or package.get('format')!='funshiki-changes-v1':raise ValueError('请选择“导出我的修改”生成的 JSON 修改包')
    if package.get('library_id')!=library_id(db):raise ValueError('修改包来自另一份资料库，不能直接合并')
    changes=package.get('changes')
    if not isinstance(changes,list) or len(changes)>50000:raise ValueError('修改包条目数量无效')
    seen=set()
    for c in changes:
        if c.get('table') not in TABLES or not isinstance(c.get('id'),str):raise ValueError('修改包记录类型无效')
        key=(c['table'],c['id'])
        if key in seen:raise ValueError('修改包有重复记录')
        seen.add(key)
        allowed=set(FIELDS[c['table']]) if c['table'] in FIELDS else {'description','p','start','end','assignment'}
        if c['table']=='series':allowed.add('work_ids')
        if not isinstance(c.get('after'),dict) or set(c['after'])!=allowed:raise ValueError('修改包包含不支持的字段')
        if c.get('before') is not None and (not isinstance(c['before'],dict) or set(c['before'])!=allowed):raise ValueError('原始字段不完整')
    return changes

def merge_value(db,key,value,package):
    if key=='target':
        if not value:return '未填写'
        field='series_id' if value['target_kind']=='series' else 'work_id'
