    if not db.execute('SELECT 1 FROM '+table+' WHERE id=?',(value['id'],)).fetchone():raise ValueError('新记录与本机已有名称或 ID 冲突，请先核对')
    if table=='series':
        for m in value.get('members',[]):insert(db,'series_works',{'series_id':value['id'],'work_id':m['work_id'],'evidence':dumps({'method':'collaboration'})})
    log_change(db,table,value['id'],None,entity(db,table,value['id']),'从协作修改包添加')

def apply_merge(db,package,fingerprint,choices=None):
    preview=preview_merge(db,package)
    if preview['fingerprint']!=fingerprint:raise ValueError('预览后本机数据有变化，请重新预览再合并')
