        for conflict in p['conflicts']:
            if resolution[conflict['field']]=='remote':values[conflict['field']]=c['after'][conflict['field']]
        if p['local_revision'] is not None and canonical(p['table'],entity(db,p['table'],p['id']))==values:continue
        plans.append((p,c,values))
    token=audit_context.set((preview['author'],'collaboration',str(package.get('package_id',''))[:100]))
    added=set();count=0
    try:
        deps=package.get('dependencies',{})
        def ensure_dependency(table,eid):
            if db.execute('SELECT 1 FROM '+table+' WHERE id=?',(eid,)).fetchone():return
            value=deps.get(table,{}).get(eid)
            if not value or value.get('id')!=eid:raise ValueError('修改包缺少依赖作品或系列：'+eid)
            if table=='series':
                for m in value.get('members',[]):ensure_dependency('works',m['work_id'])
            insert_new(db,table,value);added.add((table,eid))
        for p,c,value in sorted(plans,key=lambda x:TABLES.index(x[0]['table'])):
            table=p['table'];eid=p['id']
            if table=='entries':
                for wid in value['assignment']['work_ids']:ensure_dependency('works',wid)
            if table=='aliases':
                target=value['target'];ensure_dependency('works' if target['target_kind']=='work' else 'series',target['work_id'] or target['series_id'])
            if table=='series':
                for wid in value['work_ids']:ensure_dependency('works',wid)
            if (table,eid) in added:continue
            if p['local_revision'] is None:
                raw=c.get('record')
                if not raw or canonical(table,raw)!=value:raise ValueError('新增记录与修改内容不一致')
                insert_new(db,table,raw);count+=1;continue
            patch=dict(value)
            if table=='entries':
                assignment=patch.pop('assignment');patch.update({k:v for k,v in assignment.items() if k!='status'})
            if table=='aliases':patch.update(patch.pop('target'))
            if table=='alias_exclusions':patch={'excluded':patch['excluded']}
            update_entity(db,table,eid,patch,p['local_revision'],'合并 '+preview['author']+' 的修改');count+=1
    finally:audit_context.reset(token)
    return {'merged':count,'dependencies_added':len(added),'skipped_conflicts':skipped,'unchanged':preview['counts']['unchanged']}

