"""Data-only mobile bundles and an in-browser adapter for the same SQLite API."""
import io,json,zipfile
from pathlib import Path
from uuid import uuid4
from types import SimpleNamespace
from library import connect,initialize,dumps,now,ROOT
from library_collaboration import snapshot,library_id

def create_mobile_bundle(db,destination):
    destination=Path(destination);destination.mkdir(parents=True,exist_ok=True)
    uid=uuid4().hex;target=destination/('collaboration-'+uid+'.zip')
    clone=connect(':memory:');db.backup(clone)
    base={'snapshot':snapshot(clone),'audit_id':clone.execute('SELECT COALESCE(MAX(id),0) FROM audit_log').fetchone()[0],'at':now(),'package_id':uid}
    clone.execute("INSERT OR REPLACE INTO meta VALUES('collaboration_base',?)",(dumps(base),));clone.commit()
    manifest={'format':'funshiki-collaboration-v1','library_id':library_id(clone),'package_id':uid,'created_at':now(),'client':'browser'}
    with zipfile.ZipFile(target,'w',zipfile.ZIP_DEFLATED) as z:
        z.writestr('data/library/library.sqlite3',clone.serialize());z.writestr('manifest.json',dumps(manifest))
        z.writestr('手机和平板使用说明.txt','打开移动整理台网页，在浏览器中导入本 ZIP，无需解压或安装 Python。\n填写昵称后独立编辑，完成后导出 JSON 修改包发回主库合并。\n首次打开网页需要联网；显示离线准备完成后可断网核对。封面、原视频与 Bangumi 搜索仍需联网。\n资料仅保存在此设备的浏览器中。请定期导出修改包或恢复包，避免清理浏览器数据导致丢失。\n手机和平板网页入口：https://funshiki-anime-index.cn/mobile/')
    clone.close()
    return {'filename':target.name,'bytes':target.stat().st_size,'package_id':uid}

def import_browser_bundle(data,path):
    """Read only the known database member. Never extract executable ZIP contents."""
    with zipfile.ZipFile(io.BytesIO(data)) as z:
        info=z.getinfo('data/library/library.sqlite3')
        if info.file_size>150_000_000:raise ValueError('数据库过大，手机协作包上限为 150 MB')
        manifest=json.loads(z.read('manifest.json'))
        if manifest.get('format')!='funshiki-collaboration-v1':raise ValueError('请选择资料库生成的协作 ZIP')
        raw=z.read(info)
    if not raw.startswith(b'SQLite format 3\x00'):raise ValueError('包内数据库无效')
    probe=connect(':memory:')
    try:
        probe.deserialize(raw)
        if probe.execute('PRAGMA quick_check').fetchone()[0]!='ok':raise ValueError('数据库校验失败')
        if library_id(probe)!=manifest.get('library_id'):raise ValueError('包内资料库标识不一致')
        base=json.loads(probe.execute("SELECT value FROM meta WHERE key='collaboration_base'").fetchone()[0])
        if base['package_id']!=manifest.get('package_id'):raise ValueError('协作起点与清单不一致')
    finally:probe.close()
    Path(path).parent.mkdir(parents=True,exist_ok=True);Path(path).write_bytes(raw)
    return manifest

def browser_request(path,body=None,remote=None):
    # No HTTP listener is created. The trusted local UI invokes the existing
    # handler synchronously inside its private Web Worker.
    import library_server as server
    class Capture(server.Handler):
        def reply(self,status,value,ctype='application/json; charset=utf-8',filename=None):
            self.result={'status':status,'value':value,'content_type':ctype,'filename':filename}
    handler=Capture.__new__(Capture)
    raw=dumps(body).encode() if body is not None else b''
    handler.headers={'Host':'127.0.0.1:4175','Origin':'http://127.0.0.1:4175','X-Library-Request':'1','Content-Length':str(len(raw))}
    handler.server=SimpleNamespace(server_port=4175,db_path=ROOT/'data/library/library.sqlite3',assets_path=ROOT/'workbench')
    handler.path='/api/'+path;handler.rfile=io.BytesIO(raw)
    old_request,old_search=server.bangumi_request,server.bangumi_search
    def fetched(*args,**kwargs):
        if remote is None:raise ValueError('Bangumi 查询需要联网')
        return remote
    server.bangumi_request=fetched;server.bangumi_search=fetched
    try:
        if path=='collaboration/share':
            db=connect(handler.server.db_path)
            try:handler.reply(200,create_mobile_bundle(db,handler.server.db_path.parent/'shares'))
            finally:db.close()
        else:handler.guarded(body is not None)
        return handler.result
    finally:server.bangumi_request,server.bangumi_search=old_request,old_search

