"""Keyword extraction and date-aware series resolution using local evidence."""
from __future__ import annotations

import json
import re
from collections import defaultdict
from datetime import date, timedelta
from difflib import SequenceMatcher

from library import ROOT,add_alias,dumps,insert,norm,now,quarter,rows,stable


SEASON_RE=re.compile(r'\s*(?:第[一二三四五六七八九十百0-9]+[季期部]|(?:[1-9][0-9]*(?:st|nd|rd|th)\s+)?season\s*[0-9]*|\bpart\s*[0-9]+|第[0-9]+部分)',re.I)
BAD_PREFIX=re.compile(r'^(?:冷知识|投票|编剧|bgm|体贴企鹅|泛团|主播|这周|这集|看完|为什么|早点|总结|带货|弄的|主泛|下播时间|正片|op\b|ed\b)',re.I)
NOISE={'世界','故事','少女','少年','动画','老师','同学','第二季','第一季','第三季','下播','番剧','简评','切片','新番','第2部分','剧情','泛式','鉴赏','游戏','原作','字幕','大叔','开播','直播','时代','开始','可爱','就是','今天','感觉','这个','环节','喜欢','观看','看完','谈谈','杂谈'}


def settings():
    config=json.loads((ROOT/'config/recognition.json').read_text(encoding='utf-8'))
    extra=ROOT/'config/note-review.json'
    if extra.exists():
        review=json.loads(extra.read_text(encoding='utf-8'))
        config['keyword_hints'].extend(review['works'])
        for rule in review['families']:
            old=next((r for r in config['series'] if norm(r['name'])==norm(rule['name'])),None)
            if old:old['keywords']=list(dict.fromkeys(old['keywords']+rule['keywords']))
            else:config['series'].append(rule)
    return config


def classify_recording(title, default='talk'):
    if '燃来' in title or re.search(r'放映[会节]|MAD.*(?:大赛|鉴赏)|MAD特别鉴赏',title,re.I): return 'screening'
    if '茶话会' in title:return 'tea'
    if re.search(r'(?<![A-Za-z])(?:OP|ED)(?![A-Za-z])',title,re.I) and re.search(r'鉴赏|看.*(?:OP|ED)',title,re.I):return 'op_ed'
    return default


def base_title(name):
    name=SEASON_RE.split(name,1)[0]
    return name.strip(' 【】《》「」:：-～~!！。.')


def ensure_series(db):
    works=rows(db,'SELECT * FROM works');cfg=settings();groups=defaultdict(list);labels={}
    for w in works:
        rule=next((r for r in cfg['series'] if re.search(r['pattern'],w['name'],re.I)),None)
        name=rule['name'] if rule else base_title(w['name'])
        # Do not turn every cross-media namesake into a franchise automatically.
        key=norm(name)
        groups[key].append(w);labels[key]=(name,rule)
    for key,members in groups.items():
        name,rule=labels[key]
        qualified=bool(rule) or any(SEASON_RE.search(w['name']) for w in members)
        if not qualified:continue
        sid='series:'+stable(key)
        insert(db,'series',dict(id=sid,name=name,normalized=key,evidence=dumps({'method':'configured_family' if rule else 'season_title','pattern':rule['pattern'] if rule else None})))
        # A renamed series keeps its ID and manually maintained membership.
        actual=db.execute('SELECT * FROM series WHERE id=? OR normalized=? ORDER BY revision DESC LIMIT 1',(sid,key)).fetchone()
        sid=actual['id']
        if actual['revision']==0:
            for w in members:insert(db,'series_works',dict(series_id=sid,work_id=w['id'],evidence=dumps({'method':'name_family','name':w['name']})))
    for s in rows(db,'SELECT id,name FROM series'):
        add_alias(db,s['name'],None,'series_name','reference',{'method':'family_name'},series_id=s['id'])


def retire_generated_aliases(db):
    """Replace v1 full-sentence guesses; preserve the records as migration evidence."""
    for a in rows(db,"SELECT * FROM aliases WHERE kind='cross_source' AND status='pending' AND revision=0"):
        insert(db,'retired_aliases',dict(id=a['id'],record_json=dumps(a),reason='v2：整句候选改为提取关键词后重新识别',retired_at=now()))
        db.execute('DELETE FROM aliases WHERE id=?',(a['id'],))
    # Default-global also applies to machine seed references, retaining provenance.
    for a in rows(db,"SELECT * FROM aliases WHERE kind='legacy_seed' AND scope!='' AND revision=0"):
        add_alias(db,a['term'],a['work_id'],a['kind'],a['status'],json.loads(a['evidence']))
        insert(db,'retired_aliases',dict(id=a['id'],record_json=dumps(a),reason='v2：旧测试版自动简称改为全局',retired_at=now()))
        db.execute('DELETE FROM aliases WHERE id=?',(a['id'],))
    # Refresh unreviewed extracted candidates when rules/evidence change. Human
    # edits, confirmations and rejections remain authoritative.
    db.execute("DELETE FROM aliases WHERE kind='keyword' AND status='pending' AND revision=0")


def match_word(text,word):
    if len(word)<2:return False
    # Preserve Latin word boundaries before whitespace normalization.
    if re.fullmatch(r'[a-z0-9]+',word):
        return bool(re.search(r'(?<![a-z0-9])'+re.escape(word)+r'(?![a-z0-9])',text,re.I))
    return word in text


def extract_keywords(text,work,known,config=None):
    """Return grounded words, never fall back to accepting the full prose sentence."""
    cfg=config or settings();t=norm(text);result={}
    if BAD_PREFIX.search(text.strip()):return []
    rules=cfg['keyword_hints']+cfg['series']
    for rule in rules:
        if re.search(rule['pattern'],work['name'],re.I):
            for word in rule['keywords']:
                if match_word(t,norm(word)):
                    result[norm(word)]={'term':word,'extraction':'configured_keyword'}
    for word in known:
        token=norm(word)
        if token in NOISE or len(token)<3:continue
        if match_word(t,token):result[token]={'term':word,'extraction':'known_name'}
    if result:
        # Prefer a specific keyword over a shorter substring of that keyword.
        return [v for k,v in result.items() if not any(k!=other and k in other for other in result)]
    # A title fragment is useful only when it starts the topic heading, follows a
    # simple action prefix, or is explicitly bracketed. Incidental prose isn't a term.
    stripped=re.sub(r'^(?:然后是|接下来|下播番?\s*看?|洗干净看|时光机之|简评|聊聊|杂谈环节|下播|看|聊)\s*','',text).strip(' 《》「」【】')
    if BAD_PREFIX.search(stripped):return []
    normalized=norm(stripped)
    candidates=[]
    for name in [work['name'],work.get('original_name','')]:
        title=norm(name)
        common=SequenceMatcher(None,normalized,title,autojunk=False).find_longest_match()
        token=normalized[common.a:common.a+common.size]
        if len(token)>=3 and token not in NOISE and (common.a==0 or stripped.startswith(('《','「'))):
            if len(token)>14 and token!=normalized:continue
            if re.search(r'(?:的是|今天?|再|不|我是|其实|以及|然后)$',token):continue
            # Avoid contentless matches shared by many unrelated work titles.
            if any(token==x for x in ('异世界','不可能','的故事','女主角','男主角','第二部分','我爱你')):continue
            candidates.append(token)
    if candidates:
        token=max(candidates,key=len)
        return [{'term':token,'extraction':'title_fragment'}]
    return []


def work_start(work):
    try:return date.fromisoformat(work.get('air_date') or ''), 'air_date'
    except ValueError:
        try:return date.fromisoformat(work['quarter']+'-01'),'quarter'
        except (ValueError,TypeError,KeyError):return None,'unknown'


def number(value):
    return {'一':1,'二':2,'三':3,'四':4,'五':5,'六':6,'七':7,'八':8,'九':9,'十':10}.get(value,int(value) if value.isdigit() else None)


def media_hint(text,recording=None):
    if re.search(r'漫画|漫改原作|单行本',text):return 'manga'
    if re.search(r'轻小说|小说|文库|网文',text):return 'novel'
    if re.search(r'游戏|手游|端游|总力战|抽卡|卡池|氪金|刷图|通关|游戏联动|脚打',text):return 'game'
    if re.search(r'真人|特摄',text):return 'live_action'
    if re.search(r'剧场|电影',text):return 'movie'
    if re.search(r'\bOVA\b',text,re.I):return 'ova'
    if re.search(r'\bONA\b|网络动画',text,re.I):return 'ona'
    if (recording or {}).get('kind')=='op_ed' or re.search(r'动画|动漫|番剧|\b(?:OP|ED)\d*\b|第.{1,3}[集话]',text,re.I):return 'animation'
    return None


def resolve_series(members,recording,text):
    """Choose temporal candidates, keeping missing dates / ties explicitly uncertain."""
    if not members:return [],{'decision':'empty_series'}
    pool=list(members);basis={'recording_date':recording.get('live_date') or recording.get('published_date'),
        'recording_date_basis':'live_date' if recording.get('live_date') else 'published_date'}
    # Explicit form / season / subtitle is stronger evidence than calendar recency.
    category_hint=media_hint(text,recording)
    if category_hint:
        pool=[w for w in pool if w['category']==category_hint or (category_hint=='animation' and w['category'] in ('tv','ona','ova','movie','anime_other'))]
        basis['format']=category_hint
        if not pool:return [],{**basis,'decision':'format_not_in_library'}
    else:
        media={('animation' if w['category'] in ('tv','ona','ova','movie','anime_other') else w['category']) for w in pool}
        if len(media)>1:
            selected=[]
            for kind in sorted(media):
                subset=[w for w in pool if ('animation' if w['category'] in ('tv','ona','ova','movie','anime_other') else w['category'])==kind]
                ids,_=resolve_series(subset,recording,text);selected.extend(ids)
            return selected,{**basis,'decision':'cross_media_ambiguous','ambiguous':True}
    season=re.search(r'第([一二三四五六七八九十0-9]+)[季期]',text)
    if season:
        sn=number(season[1]);selected=[]
        for w in pool:
            m=SEASON_RE.search(w['name']);n=re.search(r'第([一二三四五六七八九十0-9]+)[季期]',w['name'])
            if (n and number(n[1])==sn) or (sn==1 and not m):selected.append(w)
        if selected:pool=selected;basis['explicit_season']=sn
        else:return [],{**basis,'decision':'explicit_season_not_in_library'}
    explicit_part=[w for w in pool if any(len(part)>=3 and norm(part) in norm(text)
                   for part in re.findall(r'[\s-]([^\s-]*(?:篇|赛段))',w['name']))]
    if explicit_part:pool=explicit_part;basis['explicit_part']=True
    if len(pool)==1 and (basis.get('explicit_season') or explicit_part):
        return [pool[0]['id']],{**basis,'decision':'explicit_member','ambiguous':False}
    retrospective=re.search(r'(?:回顾|时光机|重温).*?(20\d{2})(?:年|[-/.])\s*(\d{1,2})?月?',text+' '+recording.get('title',''))
    period=None
    if retrospective:
        year=int(retrospective[1]);month=int(retrospective[2] or 1)
        if 1<=month<=12:period=f'{year}-{((month-1)//3)*3+1:02d}';basis['context']='retrospective'
    elif recording.get('program_quarter') and (recording.get('kind') in ('tea','op_ed') or re.search(r'pv|预告|新番',recording.get('title',''),re.I)):
        period=recording['program_quarter'];basis['context']='program_quarter'
    dates={w['id']:work_start(w) for w in pool}
    undated=[w for w in pool if not dates[w['id']][0]]
    if period:
        in_period=[w for w in pool if dates[w['id']][0] and quarter(dates[w['id']][0].isoformat())==period]
        if in_period:
            pool=in_period+undated;basis['target_quarter']=period
            # A tea party before the quarter can preview future works in that quarter.
            try:cutoff=date.fromisoformat(basis['recording_date'])
            except (ValueError,TypeError):cutoff=None
            released=[w for w in pool if cutoff and dates[w['id']][0] and dates[w['id']][0]<=cutoff]
            if released:pool=released+undated
            else:return [w['id'] for w in pool],{**basis,'decision':'quarter_preview','ambiguous':len(pool)>1}
        elif basis.get('context')=='retrospective':
            return [w['id'] for w in pool],{**basis,'target_quarter':period,'decision':'retrospective_period_missing','ambiguous':True}
    try:cutoff=date.fromisoformat(basis['recording_date'])
    except (ValueError,TypeError):return [w['id'] for w in pool],{**basis,'decision':'recording_date_missing','ambiguous':True}
    if not period and re.search(r'pv|预告',text,re.I):
        upcoming=[w for w in pool if dates[w['id']][0] and cutoff<dates[w['id']][0]<=cutoff+timedelta(days=183)]
        if upcoming:
            soon=min(dates[w['id']][0] for w in upcoming)
            selected=[w for w in upcoming if dates[w['id']][0]==soon]+undated
            return [w['id'] for w in selected],{**basis,'decision':'upcoming_preview','work_date':soon.isoformat(),'ambiguous':len(selected)>1}
    eligible=[w for w in pool if dates[w['id']][0] and dates[w['id']][0]<=cutoff]
    unknown=[w for w in pool if not dates[w['id']][0]]
    if not eligible:
        return [w['id'] for w in unknown],{**basis,'decision':'no_released_member','ambiguous':True}
    latest=max(dates[w['id']][0] for w in eligible)
    selected=[w for w in eligible if dates[w['id']][0]==latest]
    return [w['id'] for w in selected+unknown],{**basis,'decision':'latest_released','work_date':latest.isoformat(),
        'work_date_basis':dates[selected[0]['id']][1],'ambiguous':bool(unknown) or len(selected)>1}


def generate_keywords(db,entries,works):
    from library_aliases import excluded_terms
    exclusions=excluded_terms(db)
    known=defaultdict(set)
    for a in rows(db,"SELECT * FROM aliases WHERE target_kind='work' AND status IN ('reference','confirmed')"):
        known[a['work_id']].add(a['term'])
    for w in works.values():known[w['id']].add(w['name'])
    cfg=settings();groups=defaultdict(list);evidence_for=defaultdict(list)
    for e in entries:
        groups[(e['recording_id'],e['p'])].append(e)
    explicit=defaultdict(set)
    for ew in rows(db,"SELECT * FROM entry_works WHERE status IN ('source','confirmed')"):
        explicit[ew['entry_id']].add(ew['work_id'])
    # Only use cross-note names that identify one known work. Never use a newly
    # inferred keyword to create more keywords in the same pass.
    named={};name_index=defaultdict(set)
    for wid,names in known.items():
        for name in names:
            token=norm(name)
            if len(token)>=3:name_index[token].add(wid)
    for e in entries:
        if not e['note_id']:continue
        hits=name_index[norm(re.sub(r'\s*(?:切片|简评|杂谈).*$', '', e['description']))]
        if len(hits)==1:named[e['id']]=hits
    membership=defaultdict(list)
    for member in rows(db,'SELECT * FROM series_works'):membership[member['work_id']].append(member['series_id'])
    for group in groups.values():
        group.sort(key=lambda e:e['start'])
        csv_anchors=[e for e in group if e['source_kind']=='archive-csv']
        note_anchors=[e for e in group if e['id'] in named or e['id'] in explicit]
        for e in group:
            if not e['note_id'] or json.loads(e['warnings']):continue
            proposed=set(explicit.get(e['id'],set()));evidence=[]
            if proposed:evidence.append({'kind':'user_or_source_link','entry_id':e['id']})
            for a in csv_anchors:
                if a['start']-10<=e['start']<=(a['end'] or a['start']):
                    proposed.update(explicit.get(a['id'],set()));evidence.append({'kind':'csv_overlap','entry_id':a['id'],'locator':a['source_locator']})
            for a in note_anchors:
                if a['note_id'] and a['note_id']!=e['note_id'] and abs(a['start']-e['start'])<=15:
                    proposed.update(named.get(a['id'],explicit.get(a['id'],set())));evidence.append({'kind':'cross_note','entry_id':a['id']})
            if len(proposed)!=1:continue
            wid=next(iter(proposed));w=works[wid]
            for keyword in extract_keywords(e['description'],w,known[wid],cfg):
                term=keyword['term'];token=norm(term)
                if token in exclusions[e['id']]:continue
                if token in {norm(n) for n in known[wid]}:continue
                # A title of another work in this very sentence isn't a nickname for w.
                if any(token==norm(other['name']) for oid,other in works.items() if oid!=wid and norm(other['name'])!=norm(w['name'])):continue
                series_id=None
                if len(membership[wid])==1 and not SEASON_RE.search(term):series_id=membership[wid][0]
                key=(token,series_id or wid)
                evidence_for[key].append({'term':term,'work_id':wid,'series_id':series_id,'entry_id':e['id'],
                    'recording_id':e['recording_id'],'original_text':e['description'],'extraction':keyword['extraction'],'evidence':evidence})
    for examples in evidence_for.values():
        example=examples[0]
        add_alias(db,example['term'],example['work_id'],'keyword','pending',
            {'extraction':example['extraction'],'examples':examples[:20],'occurrences':len(examples)},series_id=example['series_id'])


def recognize_library(db):
    from library_aliases import excluded_terms
    exclusions=excluded_terms(db)
    if db.execute("SELECT 1 FROM meta WHERE key='review_enabled' AND value='1'").fetchone():
        from library_review import review_library
        ensure_series(db)
        return review_library(db)
    retire_generated_aliases(db);ensure_series(db)
    for r in rows(db,'SELECT id,title,kind FROM recordings WHERE revision=0'):
        kind=classify_recording(r['title'],r['kind'])
        if kind!=r['kind']:db.execute('UPDATE recordings SET kind=? WHERE id=?',(kind,r['id']))
    db.execute("DELETE FROM entry_works WHERE status='candidate' AND method LIKE 'auto:%'")
    entries=rows(db,'SELECT * FROM entries');works={w['id']:w for w in rows(db,'SELECT * FROM works')}
    recordings={r['id']:r for r in rows(db,'SELECT * FROM recordings')}
    generate_keywords(db,entries,works)
    aliases=rows(db,"SELECT * FROM aliases WHERE status IN ('reference','confirmed') OR (status='pending' AND kind='keyword')")
    members=defaultdict(list)
    for m in rows(db,'SELECT * FROM series_works'):members[m['series_id']].append(works[m['work_id']])
    terms=defaultdict(list)
    for a in aliases:terms[a['normalized']].append(a)
    for w in works.values():terms[norm(w['name'])].append({'work_id':w['id'],'target_kind':'work','scope':'','id':None,'kind':'name'})
    global_words=[k for k,v in terms.items() if len(k)>=2 and any(not a['scope'] for a in v)]
    patterns=[r'(?<![a-z0-9])'+re.escape(k)+r'(?![a-z0-9])' if re.fullmatch('[a-z0-9]+',k) else re.escape(k) for k in sorted(global_words,key=len,reverse=True)]
    finder=re.compile('(?=('+'|'.join(patterns)+'))') if patterns else None
    scoped=defaultdict(set)
    for k,values in terms.items():
        for a in values:
            if a['scope']:scoped[a['scope']].add(k)
    linked=defaultdict(set);anchors=defaultdict(list)
    for ew in rows(db,"SELECT * FROM entry_works WHERE status!='candidate'"):linked[ew['entry_id']].add(ew['work_id'])
    for e in entries:
        if e['source_kind']=='archive-csv':anchors[(e['recording_id'],e['p'])].append(e)
    count=0
    for e in entries:
        if e['status']!='pending' or e['category'] in ('life','channel','general'):continue
        t=norm(e['description']);matches=defaultdict(list)
        found=set(m.group(1) for m in finder.finditer(t)) if finder else set()
        found.update(k for k in scoped[e['recording_id']] if match_word(t,k))
        found-=exclusions[e['id']]
        found={k for k in found if not any(k!=other and k in other for other in found)}
        for token in found:
            applicable=[a for a in terms[token] if not a['scope'] or a['scope']==e['recording_id']]
            explicit_work=[a for a in applicable if a['target_kind']=='work' and a.get('status')=='confirmed']
            if explicit_work and any(a['target_kind']=='series' for a in applicable):applicable=explicit_work
            series_targets={a['series_id'] for a in applicable if a['target_kind']=='series'}
            for a in applicable:
                if a['target_kind']=='series':
                    ids,why=resolve_series(members[a['series_id']],recordings[e['recording_id']],e['description'])
                    for wid in ids:matches[wid].append({'kind':'series_time','term':token,'alias_id':a['id'],'series_id':a['series_id'],**why})
                else:
                    # A series term matching the first season's exact title must not
                    # force that first season alongside the time-selected sequel.
                    if any(a['work_id'] in {w['id'] for w in members[sid]} for sid in series_targets):continue
                    matches[a['work_id']].append({'kind':'name_or_keyword','term':token,'alias_id':a['id']})
        if not json.loads(e['warnings']):
            for a in anchors[(e['recording_id'],e['p'])]:
                if a['start']-15<=e['start']<=(a['end'] or a['start']):
                    for wid in linked[a['id']]:matches[wid].append({'kind':'csv_overlap','entry_id':a['id'],'source_locator':a['source_locator']})
        if not matches and e['revision']==0 and e['category']=='unclassified':
            raw=e['description'].strip()
            cat='life' if re.fullmatch(r'(?:聊生活|生活杂谈|这周过[得的]怎么样)[?？]?',raw) or raw.startswith('生活琐事') else 'channel' if re.fullmatch(r'(?:开门|正片开始|下播时间|开播OP|下播ED|ed|结束→|开始切片|带货时间|新视频)',raw,re.I) else None
            if cat:db.execute('UPDATE entries SET category=? WHERE id=?',(cat,e['id']))
        for wid,evidence in matches.items():
            insert(db,'entry_works',dict(entry_id=e['id'],work_id=wid,status='candidate',method='auto:match',evidence=dumps(evidence)));count+=1
    return count

