def review_schema(db):
    db.executescript('''CREATE TABLE IF NOT EXISTS entry_reviews (
      entry_id TEXT PRIMARY KEY REFERENCES entries(id),reviewed_at TEXT NOT NULL,
      context_kind TEXT NOT NULL,context_quarter TEXT,method TEXT NOT NULL,evidence TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS note_reviews (
      note_id TEXT PRIMARY KEY REFERENCES notes(id),reviewed_at TEXT NOT NULL,entry_count INTEGER NOT NULL,evidence TEXT NOT NULL);''')


def infer_context(recording,text,active=None):
    """A decade marker affects its section, never every segment in that recording."""
    recorded_q=recording.get('recording_quarter') or quarter(recording.get('live_date') or recording.get('published_date'))
    program_q=recording.get('program_quarter')
    old_program=bool(program_q and recorded_q and int(program_q[:4])<int(recorded_q[:4])-2)
    q=recorded_q if old_program else program_q or recorded_q
    result={'kind':'current','quarter':q,'basis':'recording_or_program_quarter'}
    if active:result=dict(active)
    if SECTION_RE.search(text) and not re.search(r'下周|下次|什么时候|节目.*由来|视频.*支持|支持.*视频',text):
        m=re.search(r'(20\d\d)(?:年|[-/.])\s*(\d{1,2})月?',text)
        if not m and re.search(r'回顾|回忆|时光机',recording.get('title','')):m=re.search(r'(20\d\d)年\s*(\d{1,2})月',recording['title'])
        if m and 1<=int(m[2])<=12:
            result={'kind':'retrospective','quarter':f'{m[1]}-{((int(m[2])-1)//3)*3+1:02d}','basis':'explicit_past_quarter'}
        elif old_program:result={'kind':'retrospective','quarter':program_q,'basis':'explicit_program_past_quarter','marker':text}
        elif q:result={'kind':'retrospective','quarter':str(int(q[:4])-10)+q[4:],'basis':'ten_year_same_quarter','marker':text}
    if re.search(r'回到(?:本|这)(?:季|周)|本周新番|(?:下播|接着).*看|(?:7月|七月|4月|四月|一月|1月|十月|10月)新番',text) and not SECTION_RE.search(text):
        result={'kind':'current','quarter':q,'basis':'current_topic_resume'}
    if re.search(r'PV|预告|新作情报',text,re.I) and result['kind']!='retrospective':result['kind']='preview'
    return result


def metadata_work(meta):
    cat=work_category(meta)
    return dict(id='bgm:'+str(meta['id']),bangumi_id=meta['id'],name=meta.get('name_cn') or meta['name'],original_name=meta.get('name',''),
                category=cat,air_date=meta.get('date'),quarter=quarter(meta.get('date')) if cat=='tv' else None)


def metadata_names(meta):
    result=[meta.get('name',''),meta.get('name_cn','')]
    for field in meta.get('infobox',[]):
        if field.get('key') in ('别名','别称'):
            val=field.get('value');result.extend([x.get('v','') for x in val if isinstance(x,dict)] if isinstance(val,list) else [val] if isinstance(val,str) else [])
    return [x for x in result if isinstance(x,str) and x]


class Catalog:
    def __init__(self,db,metadata=None):
        cfg=json.loads((ROOT/'config/note-review.json').read_text(encoding='utf-8'))
        self.rules=cfg;self.families=settings()['series']
        path=ROOT/'data/library/season-catalog/subjects.json'
        raw=metadata if metadata is not None else json.loads(path.read_text(encoding='utf-8')) if path.exists() else {}
        self.metadata={'bgm:'+k:v for k,v in raw.items()}
        self.works={k:metadata_work(v) for k,v in self.metadata.items()}
        self.works.update({w['id']:w for w in rows(db,'SELECT * FROM works')})
        self.groups=defaultdict(set);self.family_names={};self.family_of={};self.names=defaultdict(set);self.kind={};self.display={}
        for wid,w in self.works.items():
            rule=next((r for r in self.families if self.matches(r,w)),None)
            name=rule['name'] if rule else re.sub(r'(?:\s+(?:II|III|IV|V|2|3|4|5|6)|[2-9])$','',base_title(w['name']),flags=re.I)
            family=norm(name);self.groups[family].add(wid);self.family_names[family]=name;self.family_of[wid]=family
            for n in metadata_names(self.metadata.get(wid,{})) if wid in self.metadata else [w['name'],w.get('original_name','')]:self.add_name(n,wid,'bangumi_name')
            for n in [w['name'],w.get('original_name','')]:self.add_name(n,wid,'bangumi_name')
        self.blocked=set();self.confirmed=defaultdict(set);self.confirmed_work=set();self.scoped=[];self.manual={}
        for a in rows(db,'SELECT * FROM aliases'):
            targets=[a['work_id']] if a['target_kind']=='work' else [r[0] for r in db.execute('SELECT work_id FROM series_works WHERE series_id=?',(a['series_id'],))]
            if a['scope']:
                if a['status']!='pending' or a['kind'] in ('keyword','review_keyword'):self.scoped.append((a,targets))
                continue
            if a['status']=='rejected':
                for wid in targets:self.blocked.add((a['normalized'],wid))
                continue
            if a['status']=='pending' and a['kind'] not in ('keyword','review_keyword'):continue
            if a['revision']>0:self.manual[a['normalized']]=set(targets)
            for wid in targets:
                self.add_name(a['term'],wid,'confirmed_alias' if a['status']=='confirmed' else 'source_alias')
                if a['status']=='confirmed':self.confirmed[a['normalized']].add(wid)
                if a['status']=='confirmed' and a['target_kind']=='work':self.confirmed_work.add(a['normalized'])
        self.hints=[];self.preferred={}
        for rule,is_family in [(r,True) for r in self.families]+[(r,False) for r in settings()['keyword_hints']]:
            targets={wid for wid,w in self.works.items() if self.matches(rule,w)}
            if is_family:
                manual_series=db.execute('SELECT id FROM series WHERE normalized=? AND revision>0',(norm(rule['name']),)).fetchone()
                if manual_series:targets={r[0] for r in db.execute('SELECT work_id FROM series_works WHERE series_id=?',(manual_series[0],))}
            for term in rule['keywords']:
                token=norm(term)
                if not targets:continue
                self.hints.append({'term':term,'targets':targets,'family':is_family,'pattern':rule['pattern']})
                for wid in targets:self.add_name(term,wid,'review_keyword')
                if rule.get('default_categories'):self.preferred[token]={wid for wid in targets if self.works[wid]['category'] in rule['default_categories']}
        for token,wid in self.blocked:self.names[token].discard(wid)
        # Canonical franchise names include every known installment. Explicit
        # sequel titles remain specific unless the text uses a family keyword.
        for family,ids in self.groups.items():
            if len(ids)>1:
                for wid in ids:self.add_name(self.family_names[family],wid,'family')
            elif family in self.names:self.names[family].update(ids)
        for series in rows(db,'SELECT * FROM series WHERE revision>0'):
            targets={r[0] for r in db.execute('SELECT work_id FROM series_works WHERE series_id=?',(series['id'],))}
            self.names[series['normalized']]=targets
        self.all_names={token:ids.copy() for token,ids in self.names.items()}
        for token,ids in self.confirmed.items():self.names[token]=ids.copy()
        for token,ids in self.manual.items():self.names[token]=ids.copy()
        self.trie={}
        for token in sorted(self.names,key=len,reverse=True):
            if not self.names[token] or token in NOISE or token.isdigit() or (len(token)<2 and token!='蒜'):continue
            node=self.trie
            for char in token:node=node.setdefault(char,{})
            node[None]=token
