        for token,ids in self.names.items():
            if len(token)>=4:self.prefix[token[:2]].add(token)

    @staticmethod
    def matches(rule,w):return bool(re.search(rule['pattern'],w['name'],re.I) or re.search(rule['pattern'],w.get('original_name',''),re.I))

    def add_name(self,name,wid,kind):
        token=norm(name)
        if token:self.names[token].add(wid);self.kind[(token,wid)]=kind;self.display[token]=name

    def terms(self,text,bvid):
        from library_workflow import term_present
        normalized=norm(text);found=set()
        for i in range(len(normalized)):
            node=self.trie;j=i
            while j<len(normalized) and normalized[j] in node:
                node=node[normalized[j]];j+=1;token=node.get(None)
                if token:
                    latin=re.fullmatch('[a-z0-9]+',token)
                    if not latin or term_present(text,token):found.add(token)
        scope_found=set()
        for a,ids in self.scoped:
            if a['scope']==bvid and a['status']!='rejected' and a['normalized'] in normalized:
                found.add(a['normalized']);scope_found.add(a['normalized'])
        heading=norm(re.sub(r'^(?:时光机(?:回顾)?之|简评|小聊|聊聊|聊一下|下播番?看?|然后是|看|聊)\s*','',text).lstrip('《【「'))
        found={t for t in found if t in scope_found or len(t)>3 or heading.startswith(t) or any(self.kind.get((t,wid)) in ('review_keyword','confirmed_alias') for wid in self.names[t]) or '《'+self.display.get(t,t)+'》' in text}
        return {t for t in found if not any(t!=other and t in other for other in found)}

    def choose(self,token,recording,text,context):
        ids=self.names[token].copy()
        clean=text
