            for title in (self.works[wid]['name'],self.works[wid].get('original_name','')):
                if title and re.search('游戏|漫画|小说',title):clean=re.sub(re.escape(title),'',clean,flags=re.I)
        hint=media_hint(clean,recording);media_override=False
        if hint:
            alternatives={wid for wid in self.all_names.get(token,ids) if self.works[wid]['category']==hint or (hint=='animation' and self.works[wid]['category'] in ('tv','ona','ova','movie','anime_other'))}
            if alternatives:ids=alternatives;media_override=True
            elif token in self.confirmed_work:return {},[{'term':self.display.get(token,token),'decision':'confirmed_target_media_mismatch','format':hint}]
        elif token not in self.confirmed and token not in self.manual and self.preferred.get(token):ids=self.preferred[token].copy()
        scope_blocked=set();scope_exact=False
        for a,targets in self.scoped:
            if a['scope']==recording['id'] and a['normalized']==token:
                self.display[token]=a['term']
                if a['status']=='rejected':scope_blocked.update(targets)
                elif a['status']=='confirmed' or a['revision']>0:
                    ids=set(targets);scope_exact=a['status']=='confirmed' and a['target_kind']=='work'
                else:ids.update(targets)
        ids-=scope_blocked
        if not ids:return {},[]
        byfamily=defaultdict(list)
        for wid in ids:
            if (token,wid) not in self.blocked:byfamily[self.family_of[wid]].append(self.works[wid])
        results={};unresolved=[]
        for family,members in byfamily.items():
            # A named subtitle identifies an installment even when its TV label
            # differs from the rest of the franchise (e.g. 赛马娘 巅峰之路 is ONA).
            explicit=[]
            for w in members:
                pieces=re.split(r'[\s!！/：:~～\-—]+',w['name'])
                if any(len(norm(part))>=4 and re.search('[\u4e00-\u9fff]',part) and not SEASON_RE.search(part)
                       and family not in norm(part) and norm(part) in norm(text) for part in pieces):explicit.append(w)
            if explicit:members=explicit
            if not explicit and token not in self.confirmed and not scope_exact and not media_hint(text) and all(w['category'] in ('tv','ona','ova','movie','anime_other') for w in members) and not re.search(r'剧场|电影|短片|迷你|特典|OVA|ONA',text,re.I):
                tv=[w for w in members if w['category']=='tv']
                if tv:members=tv
            if token not in self.confirmed and not scope_exact and len(members)>1:
                dated=[w for w in members if work_start(w)[0]]
                if dated:members=dated
            rec=dict(recording)
            if context['kind']=='retrospective' and context['quarter']:
                rec.update(program_quarter=context['quarter'],kind='tea')
            elif context['kind']=='preview':rec['title']+=' PV'
            if (token in self.confirmed_work and not media_override) or scope_exact:
                selected=[w['id'] for w in members];why={'decision':'confirmed_alias','ambiguous':len(selected)>1}
            else:
                # Words inside a title (亡骸游戏 / 漫画女孩) are not format hints.
                clean=text
                for name in [self.display[token]]+[n for w in members for n in (w['name'],w.get('original_name',''))]:
                    if name and re.search('游戏|漫画|小说',name):clean=re.sub(re.escape(name),'',clean,flags=re.I)
                selected,why=resolve_series(members,rec,clean)
                if not selected and why.get('decision')=='no_released_member' and re.search(r'PV|预告|茶话会',text+' '+rec['title'],re.I):
                    try:cutoff=date.fromisoformat(rec.get('live_date') or rec['published_date'])
                    except (ValueError,TypeError):cutoff=None
                    future=[w for w in members if cutoff and work_start(w)[0] and cutoff<work_start(w)[0]<=cutoff+timedelta(days=183)]
                    if future:
