            # A missing decade member must not silently pick a 2020s sequel.
            if context['kind']=='retrospective' and context['quarter']:
                period=[w['id'] for w in members if work_start(w)[0] and quarter(work_start(w)[0].isoformat())==context['quarter']]
                if period:selected=period;why.update(decision='ten_year_quarter',target_quarter=context['quarter'],ambiguous=len(period)>1)
                else:
                    older=[w['id'] for w in members if work_start(w)[0] and work_start(w)[0].year<=int(context['quarter'][:4])]
                    selected=older or selected;why.update(ambiguous=True,context_mismatch=True)
            for wid in selected:
                kind=self.kind.get((token,wid),'family')
                results[wid]={'kind':'review_name','term':self.display[token],'term_kind':kind,'context':context,**why}
                if kind in ('review_keyword','source_alias'):results[wid]['ambiguous']=True
        return results,unresolved

    def fuzzy(self,text,recording,context):
        stripped=re.sub(r'^(?:时光机(?:回顾)?之|简评|小聊|聊聊|聊一下|下播番?看?|然后是|看|聊|\d+\.)\s*','',text).strip(' 《》【】「」')
        heading=norm(re.split(r'[，,。！!？?：:（(]',stripped)[0])
        if not 4<=len(heading)<=40:return {}
        options=[]
        for name in self.prefix.get(heading[:2],[]):
            common=SequenceMatcher(None,heading,name,autojunk=False).find_longest_match()
            similarity=SequenceMatcher(None,heading[:max(len(name),6)],name,autojunk=False).ratio()
            if common.a!=0 or common.size<4 or similarity<.64:continue
            if common.size/len(heading)<.5 and common.size/len(name)<.6:continue
            chosen,_=self.choose(name,recording,text,context)
            for wid,e in chosen.items():
                q=quarter(self.works[wid].get('air_date'))
                if q==context['quarter'] or similarity>=.86:options.append((similarity,wid,{**e,'kind':'review_fuzzy','matched_title':self.display[name],'similarity':round(similarity,3),'ambiguous':True}))
        if not options:return {}
        best=max(x[0] for x in options)
        return {wid:e for score,wid,e in sorted(options,reverse=True,key=lambda x:x[0])[:3] if score>=best-.06}


def review_library(db,catalog=None):
    from library_aliases import excluded_terms
    exclusions=excluded_terms(db)
    db.execute("DELETE FROM aliases WHERE kind='review_keyword' AND status='pending' AND revision=0")
    catalog=catalog or Catalog(db);at=now();records={r['id']:r for r in rows(db,'SELECT * FROM recordings')}
    entries=rows(db,'SELECT * FROM entries');groups=defaultdict(list);anchors=defaultdict(list);links=defaultdict(set)
    for link in rows(db,"SELECT * FROM entry_works WHERE status IN ('source','confirmed')"):links[link['entry_id']].add(link['work_id'])
    for e in entries:
        if e['note_id']:groups[(e['note_id'],e['p'])].append(e)
        elif e['source_kind']=='archive-csv':anchors[(e['recording_id'],e['p'])].append(e)
    db.execute("DELETE FROM entry_works WHERE status='candidate' AND method LIKE 'auto:%'")
    plans={};direct_index=defaultdict(list);hint_examples=defaultdict(list)
    for group in groups.values():
        active=None
        for e in sorted(group,key=lambda x:(x['start'],x['id'])):
            r=records[e['recording_id']];text=e['description'];context=infer_context(r,text,active)
            if SECTION_RE.search(text):active=context
            terms=catalog.terms(text,r['id'])-exclusions[e['id']];matches={};unresolved=[]
            for token in terms:
                chosen,issues=catalog.choose(token,r,text,context);matches.update(chosen);unresolved.extend(issues)
            # A section ends when a clearly named current work resumes.
            if active and context['kind']=='retrospective' and not SECTION_RE.search(text):
                current=infer_context(r,'');new_matches={}
                for token in terms:
                    chosen,_=catalog.choose(token,r,text,current);new_matches.update(chosen)
                if new_matches and all(v.get('context_mismatch') for v in matches.values()) and any(quarter(catalog.works[w].get('air_date'))==current['quarter'] for w in new_matches):
                    matches=new_matches;context=current;active=None
            # A named work overrides a broad control-word prefix (下播看某作品).
            control=bool(EXIT_RE.search(text) or (CONTROL.search(text) and not terms))
            if control:matches={};active=None
            life=not matches and bool(LIFE_RE.search(text))
            if not matches and not control and not life and not exclusions[e['id']]:matches=catalog.fuzzy(text,r,context)
            plans[e['id']]={'entry':e,'context':context,'matches':{wid:[ev] for wid,ev in matches.items()},'control':control,'life':life,'unresolved_terms':unresolved,'csv_conflicts':[]}
            if matches and not json.loads(e['warnings']) and not any(ev['kind']=='review_fuzzy' for ev in matches.values()):direct_index[(r['id'],e['p'])].append((e,matches))
            for h in catalog.hints:
                token=norm(h['term'])
                if token in terms and h['targets'].intersection(matches):hint_examples[token].append({'entry_id':e['id'],'recording_id':r['id'],'description':text,'work_ids':sorted(h['targets'].intersection(matches))})
    for group in groups.values():
        previous=None
        ordered=sorted(group,key=lambda x:(x['start'],x['id']))
        for index,e in enumerate(ordered):
            p=plans[e['id']];text=e['description'];r=records[e['recording_id']];matches=p['matches']
            if p['control'] or p['life']:previous=None
            if not p['control'] and not p['life'] and not json.loads(e['warnings']):
                nearby=[a for a in anchors[(r['id'],e['p'])] if a['start']-15<=e['start']<(a['end'] or a['start']+1)]
                for a in nearby:
                    for wid in links[a['id']]:
                        ev={'kind':'csv_overlap','entry_id':a['id'],'source_locator':a['source_locator']}
                        if not matches or wid in matches:matches.setdefault(wid,[]).append(ev)
                        else:p['csv_conflicts'].append({'work_id':wid,**ev})
                if not matches:
                    cross=[(a,ms) for a,ms in direct_index[(r['id'],e['p'])] if a['note_id']!=e['note_id'] and abs(a['start']-e['start'])<=25]
                    ids=set().union(*(set(ms) for a,ms in cross)) if cross else set()
                    if 1<=len(ids)<=3:
                        for wid in ids:matches[wid]=[{'kind':'cross_note','entry_ids':[a['id'] for a,ms in cross if wid in ms],'ambiguous':True}]
                if not matches and previous and e['start']-previous['entry']['start']<=360 and ROLE_OR_CONTINUATION.search(text):
                    if r['kind']=='op_ed' or e['start']-previous['entry']['start']<=180:
                        for wid in previous['matches']:matches[wid]=[{'kind':'adjacent_topic','entry_id':previous['entry']['id'],'ambiguous':True}]
                if not matches and previous and e['start']-previous['entry']['start']<=600:
                    following=next((plans[a['id']] for a in ordered[index+1:] if plans[a['id']]['matches'] or plans[a['id']]['control']),None)
                    if following and not following['control'] and following['entry']['start']-e['start']<=600:
                        common=set(previous['matches']).intersection(following['matches'])
                        for wid in common:matches[wid]=[{'kind':'surrounding_topic','entry_ids':[previous['entry']['id'],following['entry']['id']],'ambiguous':True}]
            if matches and not any(ev['kind']=='adjacent_topic' for evs in matches.values() for ev in evs):previous=p
    existing={w['id'] for w in rows(db,'SELECT id FROM works')}
    used=set().union(*(set(p['matches']) for p in plans.values())) if plans else set()
    for wid in sorted(used-existing):
        if wid in catalog.metadata:add_bangumi_work(db,catalog.metadata[wid],'Bangumi seasonal reference / note review')
    ensure_series(db)
    count=0
    for eid,p in plans.items():
        e=p['entry'];matches=p['matches']
        preserved=e['status']!='pending' or (e['revision']>0 and e['category'] in ('life','channel','general'))
        if not preserved:
            if e['category'] in ('channel','life','general') and matches:db.execute("UPDATE entries SET category='unclassified' WHERE id=?",(eid,))
            if p['control'] and e['category']=='unclassified':db.execute("UPDATE entries SET category='channel' WHERE id=?",(eid,))
            if p['life'] and e['category']=='unclassified':db.execute("UPDATE entries SET category='life' WHERE id=?",(eid,))
            for wid,evidence in matches.items():
                insert(db,'entry_works',dict(entry_id=eid,work_id=wid,status='candidate',method='auto:review',evidence=dumps(evidence)));count+=1
        method='preserved_manual' if preserved else 'candidate' if matches else 'channel' if p['control'] else 'life' if p['life'] else 'unresolved'
        db.execute('INSERT OR REPLACE INTO entry_reviews VALUES (?,?,?,?,?,?)',(eid,at,p['context']['kind'],p['context']['quarter'],method,dumps({'context':p['context'],'candidate_count':len(matches),'csv_conflicts':p['csv_conflicts'],'unresolved_terms':p['unresolved_terms'],'rule_version':'corpus-review-1'})))
    # Keyword suggestions remain pending and editable; original sentences are evidence.
    for h in catalog.hints:
        token=norm(h['term']);examples=hint_examples[token]
        if not examples:continue
        targets=set().union(*(set(e['work_ids']) for e in examples))
        if h['family']:
            family=next((catalog.family_of[w] for w in targets),None)
            if family:
                sid=db.execute('SELECT id FROM series WHERE normalized=?',(family,)).fetchone()
                if sid:add_alias(db,h['term'],None,'review_keyword','pending',{'method':'corpus_review','pattern':h['pattern'],'examples':examples[:12]},series_id=sid[0]);continue
        for wid in targets:
            if wid in existing or wid in used:add_alias(db,h['term'],wid,'review_keyword','pending',{'method':'corpus_review','pattern':h['pattern'],'examples':[e for e in examples if wid in e['work_ids']][:12]})
    for n in rows(db,'SELECT id,has_timeline FROM notes'):
        reviewed=[p for p in plans.values() if p['entry']['note_id']==n['id']]
        db.execute('INSERT OR REPLACE INTO note_reviews VALUES (?,?,?,?)',(n['id'],at,len(reviewed),dumps({'has_timeline':bool(n['has_timeline']),'status':'timeline_reviewed' if reviewed else 'source_retained_without_timestamps','matched_entries':sum(bool(p['matches']) for p in reviewed)})))
    return count

