def list_data(db, table, query):
    if table=='alias_groups':return group_list(db,query)
    q=query.get('q','').strip(); page=max(1,int(query.get('page',1))); limit=50
    conditions=[]; args=[]
    def eq(field,key):
        if query.get(key): conditions.append(field+'=?');args.append(query[key])
    if table=='recordings':
        source='recording_overview'; order='COALESCE(live_date,published_date) DESC,id'
        if q: conditions.append('(title LIKE ? OR id LIKE ?)');args.extend(['%'+q+'%']*2)
        eq('kind','kind');eq('recording_quarter','quarter');eq('danmaku','danmaku')
        if query.get('missing')=='1': conditions.append('entry_count=0')
    elif table=='entries':
        source='(SELECT t.*,rv.context_kind,rv.context_quarter,rv.method review_method,cf.level confidence,cf.work_id confidence_work_id,EXISTS(SELECT 1 FROM pages pg WHERE pg.recording_id=t.recording_id AND pg.p=t.p) page_exists FROM timeline_overview t LEFT JOIN entry_reviews rv ON rv.entry_id=t.id LEFT JOIN entry_confidence cf ON cf.entry_id=t.id)';order='recording_quarter DESC,recording_id,p,start,id'
        if q:
            conditions.append('(description LIKE ? OR work_names LIKE ? OR candidates LIKE ? OR recording_title LIKE ? OR recording_id LIKE ? OR source_locator LIKE ?)')
            args.extend(['%'+q+'%']*6)
        eq('recording_id','recording');eq('status','status');eq('category','category');eq('recording_quarter','quarter')
        eq('note_id','note');eq('source_kind','source_kind')
        if query.get('warning')=='1': conditions.append("warnings!='[]'")
        if query.get('unresolved')=='1': conditions.append("work_names IS NULL AND candidates IS NULL AND status='pending'")
        if query.get('retrospective')=='1': conditions.append("context_kind='retrospective'")
        if query.get('csv_conflict')=='1': conditions.append("id IN (SELECT entry_id FROM entry_reviews WHERE json_array_length(evidence,'$.csv_conflicts')>0)")
        if query.get('confidence')=='high':conditions.append("confidence='high'")
        if query.get('work'):
            conditions.append('id IN (SELECT entry_id FROM entry_works WHERE work_id=?)');args.append(query['work'])
    elif table=='works':
        source='works';order='quarter DESC,name,id'
        if q:
            conditions.append('(name LIKE ? OR original_name LIKE ? OR CAST(bangumi_id AS TEXT)=? OR id IN (SELECT work_id FROM aliases WHERE term LIKE ?))')
            args.extend(['%'+q+'%','%'+q+'%',q,'%'+q+'%'])
        eq('category','category');eq('quarter','quarter')
        types={'2':('tv','movie','ova','ona','anime_other'),'1':('manga','novel','book'),'4':('game',),'3':('music',),'6':('live_action',)}
        if query.get('type') in types:
            categories=types[query['type']];conditions.append('category IN ('+','.join('?' for _ in categories)+')');args.extend(categories)
    elif table=='aliases':
        source='(SELECT a.*,w.name work_name,w.bangumi_id,s.name series_name FROM aliases a LEFT JOIN works w ON a.work_id=w.id LEFT JOIN series s ON s.id=a.series_id)'
        order="CASE status WHEN 'pending' THEN 0 WHEN 'confirmed' THEN 1 ELSE 2 END,term,id"
        if q: conditions.append('(term LIKE ? OR work_name LIKE ? OR series_name LIKE ?)');args.extend(['%'+q+'%']*3)
        eq('status','status');eq('kind','kind');eq('work_id','work');eq('target_kind','target_kind')
    elif table=='series':
        source='(SELECT s.*,(SELECT COUNT(*) FROM series_works sw WHERE sw.series_id=s.id) member_count FROM series s)';order='name,id'
        if q:conditions.append('name LIKE ?');args.append('%'+q+'%')
    elif table=='audit_log':
        source='audit_log';order='id DESC'
    else: raise ValueError('未知列表')
    where=' WHERE '+' AND '.join(conditions) if conditions else ''
    total=db.execute(f'SELECT COUNT(*) FROM {source}'+where,args).fetchone()[0]
    result=rows(db,f'SELECT * FROM {source}'+where+' ORDER BY '+order+' LIMIT ? OFFSET ?',(*args,limit,(page-1)*limit))
    if table=='entries':
        for e in result:
            e['links']=rows(db,'SELECT ew.*,w.name,w.bangumi_id,w.cover_url,w.category work_category,w.quarter FROM entry_works ew JOIN works w ON w.id=ew.work_id WHERE ew.entry_id=? ORDER BY ew.status,w.name',(e['id'],))
            e['source_health']=source_health(e)
    if table=='audit_log':
        for a in result:
            a['summary']=describe_change(db,a['entity'],a['entity_id'],json.loads(a['before_json']) if a['before_json'] else None,json.loads(a['after_json']))
            detail=db.execute('SELECT * FROM audit_details WHERE audit_id=?',(a['id'],)).fetchone()
            a['actor']=detail['actor'] if detail else '本机';a['origin']=detail['origin'] if detail else 'local'
    return {'items':result,'total':total,'page':page,'limit':limit}


class Handler(BaseHTTPRequestHandler):
    server_version='FunshikiLibrary/1.0'

    def reply(self,status,value,ctype='application/json; charset=utf-8',filename=None):
        body=dumps(value).encode('utf-8') if isinstance(value,(dict,list)) else value
        self.send_response(status);self.send_header('Content-Type',ctype)
        if filename:self.send_header('Content-Disposition','attachment; filename="'+filename+'"')
        self.send_header('Content-Length',str(len(body)));self.send_header('Cache-Control','no-store')
        self.send_header('X-Content-Type-Options','nosniff');self.send_header('Referrer-Policy','no-referrer')
        self.send_header('Content-Security-Policy',"default-src 'self'; img-src 'self' https:; style-src 'self'; script-src 'self'; connect-src 'self'; base-uri 'none'; frame-ancestors 'none'")
        self.end_headers();self.wfile.write(body)

    def handle_request(self, write=False):
        expected=f'127.0.0.1:{self.server.server_port}'
        if self.headers.get('Host') not in (expected,f'localhost:{self.server.server_port}'):
            return self.reply(403,{'error':'仅接受本机工作台请求'})
        parts=urlsplit(self.path);path=unquote(parts.path)
        query={k:v[0] for k,v in parse_qs(parts.query).items()}
