                        is_series=body.get('target_kind','work')=='series'
                        work_id=None if is_series else body.get('work_id')
                        series_id=body.get('series_id') if is_series else None
                        entity(db,'series' if is_series else 'works',series_id or work_id)
                        if body.get('scope') and not db.execute('SELECT 1 FROM recordings WHERE id=?',(body['scope'],)).fetchone(): raise ValueError('无效 BV 范围')
                        reason=body.get('reason') or ''
                        if not isinstance(reason,str):raise ValueError('依据应为文字，可留空')
                        if body.get('status','confirmed') not in ('pending','confirmed'): raise ValueError('无效状态')
                        existing=db.execute('SELECT * FROM aliases WHERE normalized=? AND work_id IS ? AND series_id IS ? AND scope=?',
                            (norm(body['term']),work_id,series_id,body.get('scope',''))).fetchone()
                        aid=add_alias(db,body['term'],work_id,'user',body.get('status','confirmed'),{'reason':reason},body.get('scope',''),series_id)
                        if not aid: raise ValueError('黑话不能为空')
                        result=entity(db,'aliases',aid)
                        if existing:
                            if body.get('status','confirmed')!='pending' or existing['status']=='pending':
                                result=update_entity(db,'aliases',aid,{'status':body.get('status','confirmed')},existing['revision'],reason)
                        else: log_change(db,'aliases',aid,None,result,reason)
                    elif path=='/api/series':
                        sid=create_series(db,body.get('name'),body.get('work_ids'),body.get('reason') or '')
                        result=entity(db,'series',sid)
                    elif path=='/api/recognize': result={'candidate_links':recognize(db)}
                    elif path=='/api/export': result={'directory':export_library(db,self.server.db_path.parent/'exports')}
                    elif path=='/api/undo': result=undo(db,int(body['audit_id']))
                    else: return self.reply(404,{'error':'接口不存在'})
                    if path in ('/api/update','/api/confirm-batch','/api/alias','/api/series','/api/undo','/api/collaboration/apply','/api/confirm-alias-groups','/api/alias-occurrence'):
                        if body.get('table')=='entries':suggest_reviewed_keywords(db,result['ids'] if path=='/api/confirm-batch' else [body['id']])
                        confidence=refresh_confidence(db)
                        if isinstance(result,dict):result['high_confidence_count']=confidence
                if metadata:
                    cache=self.server.db_path.parent/'bangumi-cache.json'
                    data=json.loads(cache.read_text(encoding='utf-8')) if cache.exists() else {}
                    data[str(metadata['id'])]=metadata
                    temp=cache.with_suffix('.tmp');temp.write_text(dumps(data),encoding='utf-8');temp.replace(cache)
            return self.reply(200,result)
        finally:
            if context_token:audit_context.reset(context_token)
            db.close()

    def guarded(self,write=False):
        try: self.handle_request(write)
        except (ValueError,KeyError,TypeError,sqlite3.IntegrityError) as error: self.reply(400,{'error':str(error)})
        except Exception as error:
            traceback.print_exc()
            self.reply(502,{'error':'操作未完成：'+str(error)})

    def do_GET(self): self.guarded()
    def do_POST(self): self.guarded(True)


def main():
    parser=argparse.ArgumentParser();parser.add_argument('--db',type=Path,default=DEFAULT_DB)
    parser.add_argument('--port',type=int,default=4175);parser.add_argument('--assets',type=Path,default=ROOT/'workbench');args=parser.parse_args()
    if not args.db.exists(): raise SystemExit('请先运行 python scripts/import_library.py --export')
    db=connect(args.db);initialize(db)
    # One startup backup per day; edits also retain before/after audit records.
    folder=args.db.parent/'backups';folder.mkdir(exist_ok=True)
    backup_path=folder/('workbench-'+datetime.now().strftime('%Y%m%d')+'.sqlite3')
    if not backup_path.exists():
        backup=connect(backup_path);db.backup(backup);backup.close()
    with db:refresh_confidence(db)
    db.close()
    server=ThreadingHTTPServer(('127.0.0.1',args.port),Handler);server.db_path=args.db.resolve();server.assets_path=args.assets.resolve()
    print(f'泛式资料库整理台：http://127.0.0.1:{args.port}',flush=True)
    try: server.serve_forever()
    except KeyboardInterrupt: pass
    finally: server.server_close()


if __name__=='__main__': main()

