"""Fast review operations and readable, derived review information."""
import json,re,unicodedata
from contextvars import ContextVar
from library import rows,entity,update_entity,norm,dumps,now

audit_context=ContextVar('library_audit_context',default=('本机','local',None))
LABELS={'title':'名称','name':'名称','term':'关键词','description':'时轴描述','kind':'录播类别','category':'话题 / 作品类别',
        'status':'核对状态','work_ids':'对应作品','series_id':'对应系列','work_id':'对应作品','target_kind':'指代类型','scope':'适用范围',
        'p':'分 P','start':'开始秒数','end':'结束秒数','live_date':'录播日期','published_date':'投稿日期','program_quarter':'节目季度',
        'air_date':'作品日期','quarter':'作品季度','cover_url':'封面','summary':'简介','original_name':'原名','danmaku':'弹幕版',
        'members':'系列成员','links':'作品关联','target':'黑话指代对象','excluded':'原文与黑话关联'}
VALUES={'pending':'待核对','confirmed':'已确认','rejected':'已排除','reference':'来源参考','source-imported':'CSV 已关联',
        'work':'具体作品','series':'整个系列','unclassified':'待分类','life':'生活杂谈','channel':'频道 / 新视频','general':'其他非作品话题',
        'talk':'杂谈回','tea':'茶话会','op_ed':'OP / ED 鉴赏','screening':'放映会','yes':'有弹幕版','no':'无弹幕版','unknown':'未知'}

def source_health(e):
    """Recording attribution and precise playback are independent facts."""
    issues=json.loads(e.get('warnings') or '[]');notes=[];attention=[]
    if 'source_cid_changed' in issues:notes.append('旧视频编号已变化；笔记所属录播已确定')
    if 'source_part_index_mismatch' in issues:notes.append('原笔记分 P 编号不同；已按视频信息对应')
    if 'invalid_source_tag' in issues:notes.append('原笔记跳转标签失效；不影响录播归属与作品核对')
    if not e.get('page_exists'):attention.append('只能确定所属录播，具体分 P 待补充')
    elif e.get('duration') is not None and (e['start']>e['duration'] or (e.get('end') or 0)>e['duration']):attention.append('原时点超过当前分 P 时长，精确跳转待核对')
    if 'empty_text' in issues and not e.get('description','').strip():attention.append('这个原时点没有文字描述')
    return {'recording_known':True,'jump_ready':bool(e.get('page_exists')) and not any('时长' in a for a in attention),
            'notes':notes,'attention':attention,'label':'；'.join(attention or notes),'level':'attention' if attention else 'info' if notes else 'ok'}

def display_value(db,key,value):
    if key=='excluded':return '已解绑' if value else '参与识别'
    if key in ('links','work_ids','members'):
        ids=value if key=='work_ids' else [x['work_id'] for x in (value or []) if key=='members' or x.get('status')!='candidate']
        return '、'.join((db.execute('SELECT name FROM works WHERE id=?',(wid,)).fetchone() or [wid])[0] for wid in sorted(ids or [])) or '未关联作品'
    if key in ('work_id','series_id') and value:
        table='works' if key=='work_id' else 'series'
        return (db.execute(f'SELECT name FROM {table} WHERE id=?',(value,)).fetchone() or [value])[0]
    if key=='scope':return value or '全局'
    if value is None or value=='':return '未填写'
    if isinstance(value,(dict,list)):return dumps(value)
    return VALUES.get(str(value),str(value))

def describe_change(db,table,eid,before,after):
    b=before or {};a=after or {};diff=[]
    for key in LABELS:
        if key not in a and key not in b:continue
        left=display_value(db,key,b.get(key));right=display_value(db,key,a.get(key))
        if left!=right:diff.append({'field':key,'label':LABELS[key],'before':left,'after':right})
    title=a.get('term') or a.get('name') or a.get('title') or a.get('description') or b.get('description') or eid
    if before is None:action='新增'
    elif a.get('status')=='confirmed' and b.get('status')!='confirmed':action='确认'
    elif a.get('status')=='rejected' and b.get('status')!='rejected':action='排除'
    else:action='修改'
    if table=='alias_exclusions':action='解绑原文' if a.get('excluded') else '恢复原文关联'
    context=''
    if table=='entries':
        rec=db.execute('SELECT title FROM recordings WHERE id=?',(a.get('recording_id') or b.get('recording_id'),)).fetchone()
        context=(rec[0] if rec else '')+f" · P{a.get('p') or '?'} · {a.get('start',0):g} 秒"
    if table=='alias_exclusions':
        e=db.execute('SELECT description FROM entries WHERE id=?',(a.get('entry_id'),)).fetchone()
        context=e[0] if e else ''
    return {'title':title,'action':action,'context':context,'diff':diff}

def confirm_batch(db,table,items):
    if table not in ('entries','aliases') or not isinstance(items,list) or not 1<=len(items)<=50:raise ValueError('每次确认 1 至 50 条时轴或黑话')
    if len({x['id'] for x in items})!=len(items):raise ValueError('同一条记录不能重复提交')
    # Caller wraps this in one transaction: an outdated item rolls back the page.
    results=[]
    for item in items:
        old=entity(db,table,item['id'])
        if old['status']!='pending':raise ValueError('列表中的记录已被核对，请重新读取本页')
        if table=='aliases':patch={**item.get('patch',{}),'status':'confirmed'}
        else:
            ids=item.get('work_ids',[]);cat=item.get('category','work' if ids else old['category'])
            if cat=='unclassified':raise ValueError('尚无候选的条目请先选择作品或非作品分类')
            patch={'work_ids':ids,'category':cat}
        results.append(update_entity(db,table,item['id'],patch,item['revision'],''))
    return {'confirmed':len(results),'ids':[x['id'] for x in results]}

def term_present(text,term):
    token=norm(term)
    if re.fullmatch('[a-z0-9]+',token):return bool(re.search(r'(?<![a-z0-9])'+r'[\W_]*'.join(map(re.escape,token))+r'(?![a-z0-9])',unicodedata.normalize('NFKC',text),re.I))
    return bool(token) and token in norm(text)

def refresh_confidence(db):
    """One confirmed keyword + one resolved target; never counts as human review."""
    from library_recognition import resolve_series,SEASON_RE,base_title,media_hint
    from library_aliases import excluded_terms,prune_excluded_evidence
    exclusions=excluded_terms(db);prune_excluded_evidence(db)
    aliases=rows(db,"SELECT * FROM aliases WHERE status IN ('confirmed','rejected')")
    works={w['id']:w for w in rows(db,'SELECT * FROM works')};members={}
    for a in aliases:
        members[a['id']]=[works[a['work_id']]] if a['work_id'] else [works[r[0]] for r in db.execute('SELECT work_id FROM series_works WHERE series_id=?',(a['series_id'],))]
    recordings={r['id']:r for r in rows(db,'SELECT * FROM recordings')}
    contexts={r['entry_id']:r for r in rows(db,'SELECT entry_id,context_kind,context_quarter FROM entry_reviews')}
    db.execute('DELETE FROM entry_confidence');db.execute("DELETE FROM entry_works WHERE method='auto:confirmed_alias' AND status='candidate'")
    count=0
    for e in rows(db,"SELECT * FROM entries WHERE category IN ('unclassified','work')"):
        hits=[a for a in aliases if a['normalized'] not in exclusions[e['id']] and (not a['scope'] or a['scope']==e['recording_id']) and term_present(e['description'],a['term'])]
        tokens={a['normalized'] for a in hits if a['status']=='confirmed'}
        tokens={t for t in tokens if not any(t!=u and t in u for u in tokens)}
        if len(tokens)!=1:continue
        token=next(iter(tokens));hits=[a for a in hits if a['normalized']==token]
        scoped=[a for a in hits if a['scope']]
        if scoped:hits=scoped
        hits=[a for a in hits if a['status']=='confirmed']
        if not hits:continue
        targets=set();reasons=[];uncertain=False
        for a in hits:
            rec=dict(recordings[e['recording_id']]);ctx=contexts.get(e['id'])
            if ctx and ctx['context_kind']=='retrospective':rec.update(kind='tea',program_quarter=ctx['context_quarter'])
            if a['target_kind']=='work':
                selected=[a['work_id']];why={'decision':'confirmed_specific_work'}
                hint=media_hint(e['description'],rec);cat=works[a['work_id']]['category']
                if hint and hint!=cat and not (hint=='animation' and cat in ('tv','ona','ova','movie','anime_other')):uncertain=True
            else:
                pool=members[a['id']]
                explicit=[w for w in pool if any(len(norm(part))>=4 and re.search('[\u4e00-\u9fff]',part) and not SEASON_RE.search(part)
                    and norm(part)!=norm(base_title(w['name'])) and norm(part) in norm(e['description']) for part in re.split(r'[\s!！/：:~～\-—]+',w['name']))]
                if explicit:pool=explicit
                elif not media_hint(e['description']) and all(w['category'] in ('tv','ona','ova','movie','anime_other') for w in pool):pool=[w for w in pool if w['category']=='tv'] or pool
                text=e['description']
                if ctx and ctx['context_kind']=='retrospective' and ctx['context_quarter']:text+=' 回顾 '+ctx['context_quarter']
                # Format words that are part of the work's actual title are not hints.
                for title in [a['term']]+[w['name'] for w in pool]:
                    if re.search('游戏|漫画|小说',title):text=re.sub(re.escape(title),'',text,flags=re.I)
                selected,why=resolve_series(pool,rec,text)
                uncertain|=why.get('ambiguous',False)
            targets.update(selected);reasons.append({'alias_id':a['id'],'term':a['term'],'series_id':a['series_id'],**why})
        if len(targets)!=1 or uncertain:continue
        wid=next(iter(targets));existing=rows(db,'SELECT * FROM entry_works WHERE entry_id=?',(e['id'],))
        incompatible=any(x['work_id']!=wid and (x['status']!='candidate' or any(v.get('kind')=='review_name' for v in json.loads(x['evidence']) if isinstance(v,dict))) for x in existing)
        if incompatible:continue
        proof=dumps({'method':'unique_confirmed_keyword','work_id':wid,'matches':reasons})
        db.execute('INSERT INTO entry_confidence VALUES(?,?,?,?,?)',(e['id'],'high',wid,proof,now()));count+=1
        if not any(x['work_id']==wid for x in existing) and e['status']=='pending':db.execute('INSERT INTO entry_works VALUES(?,?,?,?,?)',(e['id'],wid,'candidate','auto:confirmed_alias',dumps([{'kind':'confirmed_keyword','matches':reasons}])))
    return count


def suggest_reviewed_keywords(db,entry_ids):
    from library_recognition import extract_keywords,SEASON_RE
    from library import add_alias
    from library_aliases import excluded_terms
    exclusions=excluded_terms(db)
    for eid in entry_ids:
        e=entity(db,'entries',eid)
        if e['status']!='confirmed' or e['category']!='work' or len(e['links'])!=1:continue
        work=entity(db,'works',e['links'][0]['work_id'])
        known=[x[0] for x in db.execute("SELECT term FROM aliases WHERE work_id=? AND status IN ('reference','confirmed')",(work['id'],))]
        series=[x[0] for x in db.execute('SELECT series_id FROM series_works WHERE work_id=?',(work['id'],))]
        for keyword in extract_keywords(e['description'],work,[work['name'],*known]):
            if norm(keyword['term']) in exclusions[eid]:continue
            if norm(keyword['term']) in {norm(n) for n in [work['name'],*known]}:continue
            sid=series[0] if len(series)==1 and not SEASON_RE.search(keyword['term']) else None
            add_alias(db,keyword['term'],work['id'],'keyword','pending',{'original_text':e['description'],'entry_id':eid,'method':'confirmed_work_keyword'},series_id=sid)

