PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sources (
 id TEXT PRIMARY KEY, path TEXT NOT NULL, sha256 TEXT NOT NULL, kind TEXT NOT NULL,
 imported_at TEXT NOT NULL, details TEXT NOT NULL DEFAULT '{}'
);
CREATE TABLE IF NOT EXISTS recordings (
 id TEXT PRIMARY KEY, title TEXT NOT NULL, kind TEXT NOT NULL,
 live_date TEXT, published_date TEXT, recording_quarter TEXT, program_quarter TEXT,
 date_basis TEXT NOT NULL, danmaku TEXT NOT NULL CHECK(danmaku IN ('yes','no','unknown')),
 description TEXT NOT NULL DEFAULT '', revision INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS pages (
 recording_id TEXT NOT NULL REFERENCES recordings(id), p INTEGER NOT NULL CHECK(p>0),
 cid INTEGER, title TEXT NOT NULL, duration REAL, variant TEXT NOT NULL,
 PRIMARY KEY(recording_id,p)
);
CREATE TABLE IF NOT EXISTS recording_checks (
 recording_id TEXT PRIMARY KEY REFERENCES recordings(id),checked_at TEXT NOT NULL,
 danmaku TEXT NOT NULL,page_count INTEGER NOT NULL,evidence TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS notes (
 id TEXT PRIMARY KEY, recording_id TEXT NOT NULL REFERENCES recordings(id), cvid INTEGER,
 title TEXT NOT NULL, author TEXT NOT NULL, url TEXT NOT NULL, published TEXT,
 has_timeline INTEGER NOT NULL, content TEXT NOT NULL, issues TEXT NOT NULL DEFAULT '[]'
);
CREATE TABLE IF NOT EXISTS works (
 id TEXT PRIMARY KEY, bangumi_id INTEGER UNIQUE CHECK(bangumi_id>0), name TEXT NOT NULL,
 original_name TEXT NOT NULL DEFAULT '', type INTEGER NOT NULL DEFAULT 0,
 category TEXT NOT NULL, platform TEXT NOT NULL DEFAULT '', air_date TEXT,
 quarter TEXT, csv_quarter TEXT, quarter_basis TEXT NOT NULL,
 cover_url TEXT NOT NULL DEFAULT '', summary TEXT NOT NULL DEFAULT '',
 metadata_source TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 0,
 CHECK(category='tv' OR quarter IS NULL)
);
CREATE TABLE IF NOT EXISTS entries (
 id TEXT PRIMARY KEY, recording_id TEXT NOT NULL REFERENCES recordings(id),
 note_id TEXT REFERENCES notes(id), source_kind TEXT NOT NULL, source_locator TEXT NOT NULL,
 p INTEGER, cid INTEGER, source_cid INTEGER, start REAL NOT NULL CHECK(start>=0),
 end REAL CHECK(end>start), description TEXT NOT NULL, original_description TEXT NOT NULL,
 category TEXT NOT NULL DEFAULT 'unclassified', status TEXT NOT NULL DEFAULT 'pending',
 warnings TEXT NOT NULL DEFAULT '[]', revision INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS entry_works (
 entry_id TEXT NOT NULL REFERENCES entries(id), work_id TEXT NOT NULL REFERENCES works(id),
 status TEXT NOT NULL CHECK(status IN ('candidate','source','confirmed')),
 method TEXT NOT NULL, evidence TEXT NOT NULL,
 PRIMARY KEY(entry_id,work_id)
);
CREATE TABLE IF NOT EXISTS entry_reviews (
 entry_id TEXT PRIMARY KEY REFERENCES entries(id),reviewed_at TEXT NOT NULL,
 context_kind TEXT NOT NULL,context_quarter TEXT,method TEXT NOT NULL,evidence TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS note_reviews (
 note_id TEXT PRIMARY KEY REFERENCES notes(id),reviewed_at TEXT NOT NULL,entry_count INTEGER NOT NULL,evidence TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS series (
 id TEXT PRIMARY KEY, name TEXT NOT NULL, normalized TEXT NOT NULL UNIQUE,
 evidence TEXT NOT NULL DEFAULT '{}', revision INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS series_works (
 series_id TEXT NOT NULL REFERENCES series(id), work_id TEXT NOT NULL REFERENCES works(id),
 evidence TEXT NOT NULL DEFAULT '{}', PRIMARY KEY(series_id,work_id)
);
CREATE TABLE IF NOT EXISTS aliases (
 id TEXT PRIMARY KEY, term TEXT NOT NULL, normalized TEXT NOT NULL,
 work_id TEXT REFERENCES works(id), series_id TEXT REFERENCES series(id),
 target_kind TEXT NOT NULL DEFAULT 'work' CHECK(target_kind IN ('work','series')), kind TEXT NOT NULL,
 status TEXT NOT NULL CHECK(status IN ('reference','pending','confirmed','rejected')),
 scope TEXT NOT NULL DEFAULT '', evidence TEXT NOT NULL,
 revision INTEGER NOT NULL DEFAULT 0,
 CHECK((target_kind='work' AND work_id IS NOT NULL AND series_id IS NULL) OR
       (target_kind='series' AND series_id IS NOT NULL AND work_id IS NULL)),
 UNIQUE(normalized,work_id,scope), UNIQUE(normalized,series_id,scope)
);
CREATE TABLE IF NOT EXISTS retired_aliases (
 id TEXT PRIMARY KEY, record_json TEXT NOT NULL, reason TEXT NOT NULL, retired_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS observations (
 source_id TEXT NOT NULL REFERENCES sources(id), entity TEXT NOT NULL, entity_id TEXT NOT NULL,
 locator TEXT NOT NULL, payload TEXT NOT NULL,
 PRIMARY KEY(source_id,entity,entity_id,locator)
);
CREATE TABLE IF NOT EXISTS audit_log (
 id INTEGER PRIMARY KEY, at TEXT NOT NULL, entity TEXT NOT NULL, entity_id TEXT NOT NULL,
 reason TEXT NOT NULL, before_json TEXT, after_json TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS audit_details (
 audit_id INTEGER PRIMARY KEY REFERENCES audit_log(id), actor TEXT NOT NULL DEFAULT '本机',
 origin TEXT NOT NULL DEFAULT 'local', package_id TEXT
);
CREATE TABLE IF NOT EXISTS entry_confidence (
 entry_id TEXT PRIMARY KEY REFERENCES entries(id), level TEXT NOT NULL CHECK(level='high'),
 work_id TEXT NOT NULL REFERENCES works(id), evidence TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS alias_exclusions (
 id TEXT PRIMARY KEY,entry_id TEXT NOT NULL REFERENCES entries(id),
 term TEXT NOT NULL,normalized TEXT NOT NULL,excluded INTEGER NOT NULL DEFAULT 1 CHECK(excluded IN (0,1)),
 revision INTEGER NOT NULL DEFAULT 0,UNIQUE(entry_id,normalized)
);
CREATE INDEX IF NOT EXISTS entries_recording ON entries(recording_id,p,start);
CREATE INDEX IF NOT EXISTS entries_note ON entries(note_id);
CREATE INDEX IF NOT EXISTS entries_status ON entries(status);
CREATE INDEX IF NOT EXISTS entry_works_work ON entry_works(work_id,status);
CREATE INDEX IF NOT EXISTS aliases_normalized ON aliases(normalized);
CREATE INDEX IF NOT EXISTS aliases_work ON aliases(work_id);
CREATE INDEX IF NOT EXISTS observations_entity ON observations(entity,entity_id);
CREATE VIEW IF NOT EXISTS recording_overview AS
 SELECT r.*, (SELECT COUNT(*) FROM notes n WHERE n.recording_id=r.id AND n.has_timeline=1) timeline_notes,
 (SELECT COUNT(*) FROM entries e WHERE e.recording_id=r.id) entry_count,
 (SELECT COUNT(*) FROM entries e WHERE e.recording_id=r.id AND e.status='pending') pending_count
 FROM recordings r;
CREATE VIEW IF NOT EXISTS timeline_overview AS
 SELECT e.*,r.title recording_title,r.recording_quarter,r.program_quarter,
 n.author,n.url note_url,pg.variant,pg.duration,
 (SELECT group_concat(w.name,' / ') FROM entry_works ew JOIN works w ON w.id=ew.work_id
   WHERE ew.entry_id=e.id AND ew.status!='candidate') work_names,
 (SELECT group_concat(w.bangumi_id,' / ') FROM entry_works ew JOIN works w ON w.id=ew.work_id
   WHERE ew.entry_id=e.id AND ew.status!='candidate') bangumi_ids,
 (SELECT group_concat(w.name,' / ') FROM entry_works ew JOIN works w ON w.id=ew.work_id
   WHERE ew.entry_id=e.id AND ew.status='candidate') candidates
 FROM entries e JOIN recordings r ON r.id=e.recording_id
 LEFT JOIN notes n ON n.id=e.note_id LEFT JOIN pages pg ON pg.recording_id=e.recording_id AND pg.p=e.p;

